// Global Fetch Interceptor to automatically append the user ID header and handle auth errors
(function() {
  const originalFetch = window.fetch;
  window.fetch = async function(url, options = {}) {
    options.headers = options.headers || {};
    if (typeof state !== 'undefined' && state.currentUser && state.currentUser.id && state.currentUser.id !== "0") {
      if (options.headers instanceof Headers) {
        options.headers.set('x-user-id', state.currentUser.id);
      } else if (Array.isArray(options.headers)) {
        options.headers.push(['x-user-id', state.currentUser.id]);
      } else {
        options.headers['x-user-id'] = state.currentUser.id;
      }
    }
    try {
      const response = await originalFetch(url, options);
      if (response.status === 403) {
        try {
          const clone = response.clone();
          const data = await clone.json();
          if (data && data.error) {
            showToast(data.error, "error");
          } else {
            showToast("تم رفض العملية: لا توجد صلاحيات كافية للمستخدم.", "error");
          }
        } catch (e) {
          showToast("تم رفض العملية: لا توجد صلاحيات كافية للمستخدم.", "error");
        }
      } else if (response.status === 401) {
        showToast("انتهت الجلسة أو غير مصرح به، يرجى تسجيل الدخول مجدداً.", "warning");
      }
      return response;
    } catch (err) {
      throw err;
    }
  };
})();

