// Switch Active Tab
function switchTab(tabId) {
  state.currentTab = tabId || null;
  
  // Update Tabs Nav bar styles
  document.querySelectorAll('.tab-item').forEach(btn => {
    if (tabId && btn.id === `tab-${tabId}`) {
      btn.classList.add('active');
    } else {
      btn.classList.remove('active');
    }
  });

  // Update Panes visibility
  document.querySelectorAll('.tab-pane').forEach(pane => {
    if (tabId && pane.id === `pane-${tabId}`) {
      pane.classList.add('active');
    } else {
      pane.classList.remove('active');
    }
  });

  // Select corresponding sidebar item if any
  document.querySelectorAll('.submenu-item').forEach(el => {
    if (tabId && tabId === `menu-${el.getAttribute('data-sub-id')}`) {
      el.classList.add('active');
      
      // Auto expand parent
      const parentSection = el.closest('.menu-section');
      if (parentSection) parentSection.classList.add('open');
    } else {
      el.classList.remove('active');
    }
  });
}

// Close a Tab
function closeTab(tabId, event) {
  if (event) event.stopPropagation(); // prevent switching tab trigger

  if (tabId === 'itemCardModal') {
    const modalOverlay = document.getElementById('itemCardModalOverlay');
    if (modalOverlay) modalOverlay.remove();
    return;
  }

  // Remove tab from state
  const index = state.activeTabs.indexOf(tabId);
  if (index > -1) {
    state.activeTabs.splice(index, 1);
  }

  // Remove elements from DOM
  const tabEl = document.getElementById(`tab-${tabId}`);
  const paneEl = document.getElementById(`pane-${tabId}`);
  if (tabEl) tabEl.remove();
  if (paneEl) paneEl.remove();

  // If closed tab was the active one, switch to another
  if (state.currentTab === tabId) {
    const nextTab = state.activeTabs[state.activeTabs.length - 1] || null;
    switchTab(nextTab);
  }
}

