// Test SQL connection with form parameters
async function testDbConnection() {
  const server = DOM.dbServer.value.trim();
  const port = DOM.dbPort.value.trim() || '1433';
  const database = DOM.dbDatabase.value.trim();
  const username = DOM.dbUsername.value.trim();
  const password = DOM.dbPassword.value;

  if (!server || !database || !username) {
    showModalAlert("يرجى ملء حقول السيرفر وقاعدة البيانات واسم المستخدم لتجربة الاتصال.", "warning");
    return;
  }

  DOM.btnTestConnection.disabled = true;
  DOM.btnTestConnection.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> جاري الاختبار...';
  showModalAlert("جاري فحص الاتصال بـ SQL Server...", "info");

  try {
    const res = await fetch('/api/connect', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ server, port, database, username, password })
    });
    
    const data = await res.json();
    
    if (data.success) {
      showModalAlert(data.message, "success");
      showToast("نجح الاتصال بـ SQL Server!", "success");
    } else {
      showModalAlert(data.error || "فشل الاتصال.", "danger");
      showToast("فشل اختبار اتصال قاعدة البيانات.", "error");
    }
  } catch (err) {
    showModalAlert(`فشل اختبار الاتصال: ${err.message}`, "danger");
    showToast("خطأ بالاتصال بالشبكة.", "error");
  } finally {
    DOM.btnTestConnection.disabled = false;
    DOM.btnTestConnection.innerHTML = '<i class="fa-solid fa-rotate"></i> اختبار الاتصال';
  }
}

// Save Connection configuration & reload app data
async function saveConnectionSettings(event) {
  event.preventDefault();
  
  const server = DOM.dbServer.value.trim();
  const port = DOM.dbPort.value.trim() || '1433';
  const database = DOM.dbDatabase.value.trim();
  const username = DOM.dbUsername.value.trim();
  const password = DOM.dbPassword.value;

  DOM.btnSaveConnection.disabled = true;
  DOM.btnSaveConnection.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> جاري الحفظ والتشغيل...';

  try {
    const res = await fetch('/api/connect', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ server, port, database, username, password })
    });
    
    const data = await res.json();
    
    if (data.success) {
      showToast("تم الاتصال وحفظ الإعدادات.", "success");
      closeDbModal();
      // Reload system menus
      await loadSystemData();
      
      if (state.activeTabs.length > 0) switchTab(state.activeTabs[state.activeTabs.length - 1]);
    } else {
      showModalAlert(data.error || "فشل الاتصال.", "danger");
      showToast("خطأ بحفظ الإعدادات والاتصال.", "error");
    }
  } catch (err) {
    showModalAlert(`فشل الاتصال: ${err.message}`, "danger");
  } finally {
    DOM.btnSaveConnection.disabled = false;
    DOM.btnSaveConnection.innerHTML = '<i class="fa-solid fa-circle-check"></i> حفظ الاتصال والتشغيل';
  }
}

// Disconnect database settings
async function disconnectDb() {
  if (!confirm("هل أنت متأكد من قطع الاتصال وحذف بيانات التهيئة؟")) return;

  try {
    const res = await fetch('/api/disconnect', { method: 'POST' });
    const data = await res.json();
    if (data.success) {
      showToast(data.message, "info");
      DOM.dbServer.value = '';
      DOM.dbPort.value = '1433';
      DOM.dbDatabase.value = '';
      DOM.dbUsername.value = '';
      DOM.dbPassword.value = '';
      closeDbModal();
      await loadSystemData();
      if (state.activeTabs.length > 0) switchTab(state.activeTabs[state.activeTabs.length - 1]);
    } else {
      showToast(`فشل قطع الاتصال: ${data.error}`, "error");
    }
  } catch (err) {
    showToast(`فشل الشبكة: ${err.message}`, "error");
  }
}

// Helper to show alert inside modal
function showModalAlert(message, type) {
  DOM.modalAlert.innerHTML = `
    <div class="alert alert-${type === 'danger' ? 'warning' : type}" style="padding:10px 15px; margin-bottom:0; font-size:0.8rem;">
      <i class="fa-solid ${type === 'success' ? 'fa-circle-check' : 'fa-circle-exclamation'} alert-icon" style="font-size:1.1rem;"></i>
      <div class="alert-content">
        <p style="margin-bottom:0;">${message}</p>
      </div>
    </div>
  `;
}

// Premium toast notification system
function showToast(message, type = 'info') {
  const toast = document.createElement('div');
  toast.className = `toast toast-${type}`;
  
  let icon = 'fa-circle-info';
  if (type === 'success') icon = 'fa-circle-check';
  if (type === 'error') icon = 'fa-triangle-exclamation';
  if (type === 'warning') icon = 'fa-circle-exclamation';

  toast.innerHTML = `
    <i class="fa-solid ${icon} toast-icon"></i>
    <div class="toast-message">${message}</div>
    <i class="fa-solid fa-xmark toast-close" onclick="this.parentElement.remove()"></i>
  `;

  DOM.toastContainer.appendChild(toast);

  // Auto remove after 4.5 seconds
  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateX(-30px)';
    setTimeout(() => toast.remove(), 300);
  }, 4500);
}

// ==========================================
// LOGIN WINDOW LOGIC AND UTILITIES
// ==========================================

// 1. Start dynamic time clock ticker for "وقت الدخول"
function startClock() {
  updateClock();
  setInterval(updateClock, 1000);
}

function updateClock() {
  if (!DOM.loginTime) return;
  const now = new Date();
  
  const options = {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    second: '2-digit',
    hour12: true
  };
  
  const formatter = new Intl.DateTimeFormat('ar-EG', options);
  DOM.loginTime.value = formatter.format(now);
}

// 2. Fetch branches and users from backend API (tblBranchList & tblBranchUser)
window.loadLoginLists = async function() {
  const branchSelect = document.getElementById('loginBranchSelect') || DOM.loginBranchSelect;
  const userSelect = document.getElementById('loginUserSelect') || DOM.loginUserSelect;
  if (!branchSelect) return;

  try {
    // 1. Fetch branches list from tblBranchList
    const branchRes = await fetch('/api/branches');
    const branchResult = await branchRes.json();
    const branches = branchResult.data || branchResult.branches || [];

    branchSelect.innerHTML = '';
    if (branches.length === 0) {
      const opt = document.createElement('option');
      opt.value = '';
      opt.textContent = 'لا توجد فروع مسجلة';
      branchSelect.appendChild(opt);
      if (userSelect) userSelect.innerHTML = '<option value="">لا يوجد مستخدمين</option>';
      return;
    }

    branches.forEach((b, idx) => {
      const opt = document.createElement('option');
      opt.value = b.fldName;
      opt.textContent = b.fldName;
      opt.setAttribute('data-id', b.fldID);
      if (idx === 0) opt.selected = true;
      branchSelect.appendChild(opt);
    });

    branchSelect.selectedIndex = 0;
    const firstBranchId = branches[0].fldID;

    // 2. Fetch users allowed for this selected branch from tblBranchUser
    await loadUsersForSelectedBranch(firstBranchId);
  } catch (err) {
    console.error("Error loading login branches/users data:", err.message);
  }
};

window.loadUsersForSelectedBranch = async function(branchId) {
  const userSelect = document.getElementById('loginUserSelect') || DOM.loginUserSelect;
  if (!userSelect) return;

  try {
    const url = branchId ? `/api/users?branchId=${branchId}` : '/api/users';
    const userRes = await fetch(url);
    const userResult = await userRes.json();
    const users = userResult.data || [];

    userSelect.innerHTML = '';
    if (users.length === 0) {
      const opt = document.createElement('option');
      opt.value = '';
      opt.textContent = 'لا يوجد مستخدمين مخولين لهذا الفرع';
      userSelect.appendChild(opt);
      return;
    }

    users.forEach((u, idx) => {
      const opt = document.createElement('option');
      opt.value = u.fldName;
      opt.textContent = u.fldName;
      opt.setAttribute('data-id', u.fldID || u.fldUserID);
      if (idx === 0) opt.selected = true;
      userSelect.appendChild(opt);
    });
    userSelect.selectedIndex = 0;
  } catch (err) {
    console.error("Error loading branch users:", err.message);
  }
};

window.fetchBranchesAndUsers = function() {
  return window.loadLoginLists();
};

// Helper to fill select dropdown list
function populateDropdown(selectEl, data, valueKey, textKey) {
  if (!selectEl) return;
  selectEl.innerHTML = '';
  
  if (!data || data.length === 0) {
    const opt = document.createElement('option');
    opt.value = "";
    opt.textContent = "لا توجد خيارات متاحة";
    selectEl.appendChild(opt);
    return;
  }

  data.forEach(item => {
    const opt = document.createElement('option');
    opt.value = item[textKey]; // Select by text description
    opt.textContent = item[textKey];
    opt.setAttribute('data-id', item[valueKey]);
    selectEl.appendChild(opt);
  });
}

// 3. Get server public IP address and display in modal
async function fetchAndDisplayIP() {
  showToast("جاري الاستعلام عن عنوان IP العام لخادم التطبيق...", "info");
  
  // Set placeholder loading state in modal
  if (DOM.ipModalLink) {
    DOM.ipModalLink.textContent = "جاري جلب العنوان...";
    DOM.ipModalLink.href = "#";
  }
  openIpModal();

  try {
    const res = await fetch('/api/server-ip');
    const data = await res.json();
    
    if (data.success && data.ip) {
      const publicIp = data.ip;
      const appUrl = `http://${publicIp}:3000`;
      
      if (DOM.ipModalLink) {
        DOM.ipModalLink.textContent = appUrl;
        DOM.ipModalLink.href = appUrl;
      }
      
      // Auto copy to clipboard
      navigator.clipboard.writeText(appUrl).then(() => {
        showToast(`تم نسخ رابط الوصول الخارجي: ${appUrl}`, "success");
      });
    } else {
      throw new Error(data.error || "فشل الحصول على الـ IP من السيرفر.");
    }
  } catch (err) {
    console.warn("Server IP retrieval failed, trying client fallback:", err.message);
    try {
      const clientRes = await fetch('https://api.ipify.org?format=json');
      const clientData = await clientRes.json();
      const appUrl = `http://${clientData.ip}:3000`;
      
      if (DOM.ipModalLink) {
        DOM.ipModalLink.textContent = appUrl;
        DOM.ipModalLink.href = appUrl;
      }
      
      navigator.clipboard.writeText(appUrl).then(() => {
        showToast(`تم نسخ رابط الوصول العام للشبكة: ${appUrl}`, "success");
      });
    } catch (e) {
      if (DOM.ipModalLink) {
        DOM.ipModalLink.textContent = "فشل الاتصال بالإنترنت لجلب عنوان الـ IP العام.";
        DOM.ipModalLink.href = "#";
      }
      showToast("فشل جلب عنوان IP العام. يرجى التحقق من اتصال الإنترنت.", "error");
    }
  }
}

// Permissions Helper Functions
async function fetchUserPermissions(userId) {
  try {
    const res = await fetch(`/api/permissions/${userId}`);
    const data = await res.json();
    if (data.success) {
      state.permissions = data.data || [];
    } else {
      state.permissions = [];
      showToast(data.error || "فشل تحميل صلاحيات المستخدم", "error");
    }
  } catch (err) {
    console.error("Error loading permissions:", err);
    state.permissions = [];
  }
}

function applySidebarPermissions() {
  const isAdmin = state.currentUser && (
    state.currentUser.isAdmin || 
    state.currentUser.fldAdmin || 
    String(state.currentUser.id) === "1"
  );

  if (isAdmin || !state.permissions || state.permissions.length === 0) {
    renderSidebar(state.menus || []);
    return;
  }

  const filteredMenus = (state.menus || []).filter(menu => {
    const perm = state.permissions.find(p => p.fldMenuID === menu.fldID);
    if (!perm) return false;
    return !!perm.fldSELECT;
  });

  if (filteredMenus.length === 0) {
    renderSidebar(state.menus || []);
  } else {
    renderSidebar(filteredMenus);
  }
}

window.hasPermission = function(menuId, action) {
  const isAdmin = state.currentUser && (
    state.currentUser.isAdmin || 
    state.currentUser.fldAdmin || 
    String(state.currentUser.id) === "1"
  );
  if (isAdmin) return true;

  if (!state.permissions || state.permissions.length === 0) return true;

  const perm = state.permissions.find(p => p.fldMenuID === menuId);
  if (!perm) return true;
  
  return !!perm[action];
};

// 4. Validate credentials and process login
async function submitLoginForm() {
  // Clear previous visual errors
  clearAllLoginErrors();

  const userSelect = DOM.loginUserSelect;
  const selectedUserOpt = userSelect ? userSelect.options[userSelect.selectedIndex] : null;
  const userId = selectedUserOpt ? selectedUserOpt.getAttribute('data-id') : "0";
  const username = userSelect ? userSelect.value : "";

  const password = DOM.loginPassword ? DOM.loginPassword.value : "";
  const branchSelect = DOM.loginBranchSelect;
  const selectedBranchOpt = branchSelect ? branchSelect.options[branchSelect.selectedIndex] : null;
  const branchId = selectedBranchOpt ? selectedBranchOpt.getAttribute('data-id') : null;
  const branchName = branchSelect ? branchSelect.value : "";

  let hasValidationError = false;

  if (!branchName) {
    showLoginError(DOM.loginBranchSelect, 'loginBranchError', 'يرجى اختيار الفرع أولاً.');
    hasValidationError = true;
  }

  if (!username) {
    showLoginError(DOM.loginUserSelect, 'loginUserError', 'يرجى اختيار اسم المستخدم أولاً.');
    hasValidationError = true;
  }

  if (!password) {
    showLoginError(DOM.loginPassword, 'loginPasswordError', 'يرجى إدخال كلمة السر.');
    hasValidationError = true;
  }

  if (hasValidationError) {
    showToast("يرجى تعبئة الحقول المطلوبة وتصحيح الأخطاء الموضحة.", "warning");
    return;
  }

  const submitBtn = DOM.loginSubmitBtn || document.getElementById('loginSubmitBtn');
  const originalBtnHtml = submitBtn ? submitBtn.innerHTML : '';

  try {
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> <span>جاري التحقق...</span>`;
    }

    const res = await fetch('/api/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password, branchId })
    });

    const data = await res.json();

    if (data.success) {
      showToast(data.message, "success");
      
      // Hide login overlay & reveal main app IMMEDIATELY
      if (DOM.loginOverlay) DOM.loginOverlay.style.display = 'none';
      const appContainer = document.querySelector('.app-container');
      if (appContainer) appContainer.classList.remove('hidden');

      // Update top account menu details
      const headerUser = document.getElementById('headerCurrentUserName');
      if (headerUser) headerUser.textContent = username || (data.user && data.user.name) || "المستخدم";
      const menuUserBadge = document.getElementById('menuUserBadgeName');
      if (menuUserBadge) menuUserBadge.textContent = username || (data.user && data.user.name) || "المستخدم";
      const menuBranchBadge = document.getElementById('menuBranchBadgeName');
      if (menuBranchBadge) menuBranchBadge.textContent = branchName || "الفرع الرئيسي";

      // Determine provider name from connection status (database name) or default
      const providerName = (state.connectionStatus && state.connectionStatus.connected && state.connectionStatus.details && state.connectionStatus.details.database) 
        ? state.connectionStatus.details.database 
        : "عرض تجريبي";

      // Save current authenticated user metadata to link across views
      state.currentUser = { 
        id: userId, 
        name: username,
        isAdmin: (data.user && (data.user.isAdmin || data.user.fldAdmin)) || String(userId) === "1"
      };
      state.currentBranch = { id: branchId || "1", name: branchName || providerName };

      // Update welcome message inside Home tab dashboard dynamically
      const finalBranchName = branchName || providerName;
      const branchHeaderName = document.getElementById('branchHeaderName');
      if (branchHeaderName) {
        branchHeaderName.innerHTML = `${finalBranchName} &gt;&gt; مستكشف الحسابات (المستخدم: ${username} | الرقم: ${userId})`;
      }

      // Update provider name inside header breadcrumbs
      const providerHeaderName = document.getElementById('providerHeaderName');
      if (providerHeaderName) {
        providerHeaderName.textContent = providerName;
      }
      
      // Update welcome title
      const welcomeTitle = document.querySelector('.welcome-text h1');
      if (welcomeTitle) {
        welcomeTitle.textContent = `مستكشف حسابات ومبيعات ${providerName}`;
      }

      // Update welcome description card
      const welcomeLabel = document.querySelector('.welcome-text p');
      if (welcomeLabel) {
        welcomeLabel.innerHTML = `أهلاً بك في نظام إدارة ومبيعات ${providerName}. <strong>المستكشف مسجل باسم: ${username} (رقم المعرّف: ${userId})</strong>. تصفح القوائم الجانبية لفتح شاشات العمل.`;
      }

      // Update browser window title
      document.title = `مستكشف الحسابات | ${providerName}`;
      
      // Clear password field for security
      if (DOM.loginPassword) DOM.loginPassword.value = '';

      // Async load permissions and logo settings in background without blocking screen display
      fetchUserPermissions(userId).then(() => applySidebarPermissions()).catch(console.error);
      fetchLogoSettings().catch(console.error);
      
      // Show login summary popup modal (Balances & Pending Transactions)
      if (typeof window.showLoginSummaryModal === 'function') {
        window.showLoginSummaryModal().catch(console.error);
      }

      // Focus on main system menu search field (sidebar filter)
      if (DOM.sidebarFilter) {
        DOM.sidebarFilter.focus();
        DOM.sidebarFilter.select();
      }
    } else {
      showToast(data.error || "فشل التحقق من الهوية.", "error");
      
      // Show exact error on field
      if (data.error && (data.error.includes("كلمة المرور") || data.error.includes("كلمة السر"))) {
        showLoginError(DOM.loginPassword, 'loginPasswordError', data.error);
        if (DOM.loginPassword) DOM.loginPassword.focus();
      } else if (data.error && data.error.includes("المستخدم")) {
        showLoginError(DOM.loginUserSelect, 'loginUserError', data.error);
        if (DOM.loginUserSelect) DOM.loginUserSelect.focus();
      } else {
        showLoginError(DOM.loginPassword, 'loginPasswordError', data.error || 'فشل التحقق من البيانات.');
        if (DOM.loginPassword) DOM.loginPassword.focus();
      }
    }
  } catch (err) {
    showToast(`خطأ في عملية التحقق: ${err.message}`, "error");
  } finally {
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.innerHTML = originalBtnHtml;
    }
  }
}

// Bind Enter key on login form submit
window.handleLoginSubmit = function(event) {
  event.preventDefault();
  submitLoginForm();
};

// Reset login form fields
window.resetLoginForm = function() {
  if (DOM.loginForm) {
    DOM.loginForm.reset();
    if (DOM.loginPassword) {
      DOM.loginPassword.value = '1';
    }
    clearAllLoginErrors();
    showToast("تم إعادة تهيئة حقول تسجيل الدخول.", "info");
    
    // Focus back on Year
    if (DOM.loginYear) {
      DOM.loginYear.focus();
      DOM.loginYear.select();
    }
  }
};

// --- Login Validation Utilities ---
function showLoginError(inputEl, errorId, message) {
  if (!inputEl) return;
  const wrapper = inputEl.closest('.login-field-input-wrapper');
  if (wrapper) wrapper.classList.add('has-error');
  
  const errEl = document.getElementById(errorId);
  if (errEl) {
    errEl.textContent = message;
    errEl.style.display = 'block';
  }
}

function clearFieldVisualError(inputEl, errorId) {
  if (!inputEl) return;
  const wrapper = inputEl.closest('.login-field-input-wrapper');
  if (wrapper) wrapper.classList.remove('has-error');
  
  const errEl = document.getElementById(errorId);
  if (errEl) {
    errEl.textContent = '';
    errEl.style.display = 'none';
  }
}

function clearAllLoginErrors() {
  document.querySelectorAll('.login-field-input-wrapper').forEach(el => el.classList.remove('has-error'));
  document.querySelectorAll('.login-field-error-msg').forEach(el => {
    el.textContent = '';
    el.style.display = 'none';
  });
}

