// CHART OF ACCOUNTS (الحساب) TREE-GRID SERVICE
// ==========================================

// Fetch accounts from backend endpoint
window.fetchAccountsTree = async function(tabId) {
  const tbody = document.getElementById(`accountsBody-${tabId}`);
  if (!tbody) return;

  tbody.innerHTML = `
    <tr>
      <td colspan="6" style="text-align: center; padding: 40px; color: var(--text-muted);">
        <div class="spinner" style="margin: 0 auto 12px;"></div>
        جاري تحميل شجرة الحسابات بقاعدة البيانات...
      </td>
    </tr>
  `;

  try {
    const res = await fetch('/api/accounts');
    const result = await res.json();

    if (result.data) {
      state.accounts = result.data; // Store accounts in global state
      showToast("تم تحميل بيانات شجرة الحسابات بنجاح.", "success");
      renderAccountsTree(result.data, tabId);
    } else {
      showToast("خطأ أثناء استعلام الحسابات.", "error");
    }
  } catch (err) {
    showToast(`فشل الاتصال: ${err.message}`, "error");
  }
};

// Render accounts rows recursively inside table
function renderAccountsTree(accountsList, tabId) {
  const tbody = document.getElementById(`accountsBody-${tabId}`);
  if (!tbody) return;

  tbody.innerHTML = '';

  const treeData = compileTreeGrid(accountsList);

  treeData.forEach(node => {
    const tr = document.createElement('tr');
    tr.className = `accounts-row tree-depth-${node.depth}`;
    tr.setAttribute('data-id', node.fldID);
    tr.setAttribute('data-parent', node.fldParentID || '');
    tr.setAttribute('data-depth', node.depth);
    tr.setAttribute('data-expanded', 'true');
    tr.style.cursor = 'pointer';

    tr.onclick = (e) => {
      if (e.target.closest('.tree-toggle-icon')) return;
      tbody.querySelectorAll('.accounts-row').forEach(row => row.classList.remove('selected-row'));
      tr.classList.add('selected-row');
      state.selectedAccountID = node.fldID;
    };

    tr.ondblclick = (e) => {
      if (e.target.closest('.tree-toggle-icon')) return;
      tbody.querySelectorAll('.accounts-row').forEach(row => row.classList.remove('selected-row'));
      tr.classList.add('selected-row');
      state.selectedAccountID = node.fldID;
      openEditAccountModal(tabId);
    };

    // RTL Padding based on tree depth indentation
    const paddingRight = (node.depth * 25) + 12;

    let toggleIcon = '';
    if (node.hasChildren) {
      toggleIcon = `<span class="tree-toggle-icon expanded" onclick="toggleTreeNode(event, '${tabId}', '${node.fldID}')"><i class="fa-solid fa-chevron-down"></i></span>`;
    } else {
      toggleIcon = `<span class="tree-leaf-spacer"></span>`;
    }

    tr.innerHTML = `
      <td style="padding-right: ${paddingRight}px; text-align: right;">
        ${toggleIcon}
        <span class="tree-node-name">${node.fldName}</span>
      </td>
      <td style="font-weight: 700; color: #4a5568;">${node.fldAccountNo}</td>
      <td style="text-align: center;">
        <input type="checkbox" class="grid-checkbox" ${node.fldActive ? 'checked' : ''} disabled>
      </td>
      <td style="color: #718096;">${node.fldParentName || ''}</td>
      <td><span class="badge" style="background: #edf2f7; color: #4a5568; padding: 2px 6px; border-radius: 4px;">${node.fldGroup || 'حساب عام'}</span></td>
      <td><span class="badge" style="background: #ebf8ff; color: #2b6cb0; padding: 2px 6px; border-radius: 4px;">${node.fldFinalAccount || '1-ميزانيه'}</span></td>
    `;

    tbody.appendChild(tr);
  });
}

// Compile recursive DFS tree-grid flat array
function compileTreeGrid(list) {
  // Normalize and map database and mock structure to a unified schema
  const normalizedList = list.map(item => {
    const parentName = item.fldParentName || (item.fldParentID ? (list.find(p => p.fldID === item.fldParentID)?.fldName || '') : '');
    return {
      fldID: item.fldID,
      fldParentID: item.fldParentID,
      fldName: item.fldName,
      fldAccountNo: String(item.fldAccountNo !== undefined ? item.fldAccountNo : (item.fldNumber !== undefined ? item.fldNumber : '')),
      fldActive: item.fldActive !== undefined ? item.fldActive : (item.fldIsActive !== undefined ? item.fldIsActive : false),
      fldParentName: parentName,
      fldGroup: item.fldGroup || (item.fldIs_Primary ? 'حساب رئيسي' : 'حساب فرعي'),
      fldFinalAccount: item.fldFinalAccount || '1-ميزانيه'
    };
  });

  const childrenMap = {};
  const roots = [];

  normalizedList.forEach(item => {
    const parentId = item.fldParentID;
    if (parentId === null || parentId === undefined || parentId === 0 || parentId === "0" || parentId === "") {
      roots.push(item);
    } else {
      if (!childrenMap[parentId]) {
        childrenMap[parentId] = [];
      }
      childrenMap[parentId].push(item);
    }
  });

  // Sort by Account Number
  roots.sort((a, b) => a.fldAccountNo.localeCompare(b.fldAccountNo));
  Object.keys(childrenMap).forEach(key => {
    childrenMap[key].sort((a, b) => a.fldAccountNo.localeCompare(b.fldAccountNo));
  });

  const flatResult = [];

  function traverse(node, depth) {
    const children = childrenMap[node.fldID] || [];
    flatResult.push({
      ...node,
      depth: depth,
      hasChildren: children.length > 0
    });

    children.forEach(child => {
      traverse(child, depth + 1);
    });
  }

  roots.forEach(root => {
    traverse(root, 0);
  });

  return flatResult;
}

// Toggle tree collapse / expand node branches
window.toggleTreeNode = function(event, tabId, nodeId) {
  event.stopPropagation();
  const icon = event.currentTarget;
  const tr = icon.closest('tr');
  const isExpanded = tr.getAttribute('data-expanded') === 'true';

  if (isExpanded) {
    tr.setAttribute('data-expanded', 'false');
    icon.classList.remove('expanded');
    icon.classList.add('collapsed');
    hideNodeChildren(tabId, nodeId);
  } else {
    tr.setAttribute('data-expanded', 'true');
    icon.classList.remove('collapsed');
    icon.classList.add('expanded');
    showNodeChildren(tabId, nodeId);
  }
};

function hideNodeChildren(tabId, parentId) {
  const tbody = document.getElementById(`accountsBody-${tabId}`);
  if (!tbody) return;
  const rows = tbody.querySelectorAll('tr.accounts-row');

  const childIds = [];
  rows.forEach(row => {
    const pId = row.getAttribute('data-parent');
    const rId = row.getAttribute('data-id');
    if (pId === String(parentId)) {
      row.classList.add('tree-row-collapsed');
      childIds.push(rId);
    }
  });

  childIds.forEach(cId => hideNodeChildren(tabId, cId));
}

function showNodeChildren(tabId, parentId) {
  const tbody = document.getElementById(`accountsBody-${tabId}`);
  if (!tbody) return;
  const rows = tbody.querySelectorAll('tr.accounts-row');

  rows.forEach(row => {
    const pId = row.getAttribute('data-parent');
    if (pId === String(parentId)) {
      row.classList.remove('tree-row-collapsed');

      const isExpanded = row.getAttribute('data-expanded') === 'true';
      const rId = row.getAttribute('data-id');
      if (isExpanded) {
        showNodeChildren(tabId, rId);
      }
    }
  });
}

