window.initJournalEntriesTab = async function(tabId) {
  state.journalCurrentTabId = tabId;
  const branchSelect = document.getElementById(`journalFilterBranch-${tabId}`);
  if (!branchSelect) return;

  try {
    // 1. Populate branches
    await ensureVoucherMetadata();
    populateSelect(branchSelect, state.userBranches.length > 0 ? state.userBranches : state.branches, 'fldID', 'fldName');

    // 2. Fetch journal entries immediately
    fetchJournalEntries(tabId);
  } catch (err) {
    console.error("Error initializing journal entries tab:", err);
  }
};

window.fetchJournalEntries = async function(tabId) {
  const tbody = document.getElementById(`journalBody-${tabId}`);
  if (!tbody) return;

  const branchNo = document.getElementById(`journalFilterBranch-${tabId}`).value;
  const description = document.getElementById(`journalFilterDescription-${tabId}`).value;
  const startDate = document.getElementById(`journalFilterStartDate-${tabId}`).value;
  const endDate = document.getElementById(`journalFilterEndDate-${tabId}`).value;

  tbody.innerHTML = `
    <tr>
      <td colspan="7" style="text-align: center; padding: 40px; color: var(--text-muted);">
        <div class="spinner" style="margin: 0 auto 12px;"></div>
        جاري تحميل القيود...
      </td>
    </tr>
  `;

  try {
    const url = new URL('/api/journal-entries', window.location.origin);
    url.searchParams.append('startDate', startDate);
    url.searchParams.append('endDate', endDate);
    if (branchNo) url.searchParams.append('branchNo', branchNo);
    if (description) url.searchParams.append('description', description);

    const res = await fetch(url.toString());
    const result = await res.json();

    if (result.data) {
      showToast("تم تحميل القيود بنجاح.", "success");
      renderJournalEntriesGrid(result.data, tabId);
    } else {
      showToast("خطأ أثناء استعلام القيود.", "error");
    }
  } catch (err) {
    showToast(`فشل الاتصال: ${err.message}`, "error");
  }
};

function renderJournalEntriesGrid(entriesList, tabId) {
  const tbody = document.getElementById(`journalBody-${tabId}`);
  if (!tbody) return;

  tbody.innerHTML = '';

  if (!entriesList || entriesList.length === 0) {
    tbody.innerHTML = `
      <tr>
        <td colspan="7" style="text-align: center; padding: 40px; color: var(--text-muted);">
          <i class="fa-solid fa-folder-open" style="font-size: 1.5rem; margin-bottom: 8px; display: block; color: var(--text-muted);"></i>
          لا توجد قيود تطابق خيارات التصفية المحددة.
        </td>
      </tr>
    `;
    return;
  }

  entriesList.forEach(e => {
    const tr = document.createElement('tr');
    tr.style.cursor = 'pointer';
    tr.setAttribute('data-id', e.fldTransID);

    tr.onclick = () => {
      tbody.querySelectorAll('tr').forEach(row => row.classList.remove('selected-row'));
      tr.classList.add('selected-row');
      state.selectedJournalID = e.fldTransID;
    };

    tr.ondblclick = () => {
      tbody.querySelectorAll('tr').forEach(row => row.classList.remove('selected-row'));
      tr.classList.add('selected-row');
      state.selectedJournalID = e.fldTransID;
      openEditJournalEntryModal(tabId);
    };

    const okIcon = e.fldOK ? '<i class="fa-solid fa-circle-check" style="color: var(--success);"></i>' : '<i class="fa-solid fa-circle-xmark" style="color: var(--text-muted); opacity: 0.5;"></i>';
    const closedIcon = e.fldClosed ? '<i class="fa-solid fa-lock" style="color: #e53e3e;"></i>' : '<i class="fa-solid fa-lock-open" style="color: var(--text-muted); opacity: 0.5;"></i>';
    const totalVal = parseFloat(e.fldVoisherTotal) || 0;
    const totalStr = formatDecimal(totalVal);
    const dateStr = e.fldDate ? new Date(e.fldDate).toISOString().substring(0, 10) : '';

    tr.innerHTML = `
      <td style="text-align: center; vertical-align: middle;">${okIcon}</td>
      <td style="text-align: center; vertical-align: middle;">${closedIcon}</td>
      <td style="font-weight: bold; text-align: center;">${e.fldTransNo || ''}</td>
      <td style="text-align: center;">${dateStr}</td>
      <td>${e.fldBranchName || ''}</td>
      <td style="text-align: left; font-family: monospace; font-weight: bold; color: var(--primary);">${totalStr}</td>
      <td style="color: #4a5568;">${e.fldDescription || ''}</td>
    `;

    tbody.appendChild(tr);
  });
}

