window.initAccountStatementTab = async function(tabId) {
  try {
    await ensureVoucherMetadata();

    // 1. Populate Branches
    const branchSelect = document.getElementById(`asBranch-${tabId}`);
    if (branchSelect) {
      populateSelect(branchSelect, state.userBranches.length > 0 ? state.userBranches : state.branches, 'fldID', 'fldName');
    }

    // 2. Populate Currencies
    const currencySelect = document.getElementById(`asCurrency-${tabId}`);
    if (currencySelect) {
      currencySelect.innerHTML = '<option value="">كل العملات</option>';
      populateSelect(currencySelect, state.currencies, 'fldID', 'fldName');
    }

    // 3. Populate Cost Centers
    const costCenterSelect = document.getElementById(`asCostCenter-${tabId}`);
    if (costCenterSelect) {
      costCenterSelect.innerHTML = '<option value="">كل المراكز</option>';
      try {
        const res = await fetch('/api/cost-centers');
        const ccData = await res.json();
        const centers = ccData.data || [];
        populateSelect(costCenterSelect, centers, 'fldID', 'fldName');
      } catch (e) {
        console.error("Error loading cost centers for statement:", e);
      }
    }

    // 4. Populate Account Groups
    const groupSelect = document.getElementById(`asGroup-${tabId}`);
    if (groupSelect) {
      groupSelect.innerHTML = '<option value="">كل المجموعات</option>';
      try {
        const res = await fetch('/api/account-groups');
        const gData = await res.json();
        const groups = gData.data || [];
        populateSelect(groupSelect, groups, 'fldID', 'fldName');
      } catch (e) {
        console.error("Error loading account groups for statement:", e);
      }
    }

    // 5. Setup Dates
    const startDateInput = document.getElementById(`asStartDate-${tabId}`);
    const endDateInput = document.getElementById(`asEndDate-${tabId}`);
    const today = new Date();
    const currentYear = today.getFullYear();
    const currentMonth = String(today.getMonth() + 1).padStart(2, '0');
    
    if (startDateInput) {
      startDateInput.value = `${currentYear}-${currentMonth}-01`;
    }
    if (endDateInput) {
      endDateInput.value = today.toISOString().substring(0, 10);
    }

    // 6. Populate Searchable Accounts datalist
    updateAccountStatementDatalist(tabId);

  } catch (err) {
    console.error("Error initializing account statement tab:", err);
  }
};

function updateAccountStatementDatalist(tabId) {
  const datalist = document.getElementById(`asAccountsDatalist-${tabId}`);
  if (!datalist) return;
  
  datalist.innerHTML = (state.accounts || []).map(acc => {
    return `<option value="${acc.fldNumber} - ${acc.fldName}" data-id="${acc.fldID}"></option>`;
  }).join('');
}

window.onAccountStatementSearchChange = function(tabId, value) {
  const accIdInput = document.getElementById(`asAccID-${tabId}`);
  if (!accIdInput) return;

  if (!value) {
    accIdInput.value = '';
    return;
  }

  const parts = value.split(' - ');
  const accNumber = parts[0].trim();
  const acc = (state.accounts || []).find(a => String(a.fldNumber) === String(accNumber));

  if (acc) {
    accIdInput.value = acc.fldID;
  } else {
    accIdInput.value = '';
  }
};

window.toggleAccountStatementCurrency = function(tabId) {
  if (state.lastStatementResult && state.lastStatementResult[tabId]) {
    renderAccountStatementTable(tabId, state.lastStatementResult[tabId]);
  }
};

