window.sendAccountGroupWhatsApp = async function(tabId) {
  const statement = state.accountGroupStatement ? state.accountGroupStatement[tabId] : null;
  if (!statement || !statement.transactions || statement.transactions.length === 0) {
    showToast("يرجى اختيار مجموعة الحسابات وإجراء الاستعلام أولاً لإرسال الكشف.", "warning");
    return;
  }

  const phoneInput = prompt("أدخل رقم الواتساب لإرسال كشف حركة مجموعة الحسابات كـ PDF (بصيغة دولية وبدون أصفار أو + مثل 967777777777):");
  if (phoneInput === null) return;

  const cleanPhone = phoneInput.replace(/[^0-9]/g, '');
  if (!cleanPhone || cleanPhone.length < 8) {
    showToast("رقم الواتساب غير صالح.", "error");
    return;
  }

  showToast("جاري إعداد تقرير PDF وإرساله عبر الواتساب...", "info");

  try {
    const res = await fetch('/api/account-statement/send-whatsapp-pdf', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        groupIdFrom: statement.groupIdFrom ? parseInt(statement.groupIdFrom) : null,
        groupIdTo: statement.groupIdTo ? parseInt(statement.groupIdTo) : null,
        branchNo: statement.branchId ? parseInt(statement.branchId) : null,
        startDate: statement.startDate || null,
        endDate: statement.endDate || null,
        phone: cleanPhone,
        isLocal: true // Local currency statement
      })
    });

    const result = await res.json();
    if (result.success) {
      showToast(result.message || "تم إرسال كشف حركة مجموعة الحسابات بالواتساب بنجاح!", "success");
    } else {
      showToast("خطأ أثناء إرسال الواتساب: " + (result.error || "فشل العملية"), "error");
    }
  } catch (err) {
    console.error("Error sending account group statement via WhatsApp:", err);
    showToast("حدث خطأ أثناء الاتصال بالخادم لإرسال الكشف.", "error");
  }
};

