      const pDeb = parseFloat(row.PeriodDebit) || 0;
      const pCr = parseFloat(row.PeriodCredit) || 0;
      const pDebL = parseFloat(row.PeriodDebitLocal) || 0;
      const pCrL = parseFloat(row.PeriodCreditLocal) || 0;

