window.sendAccountReportsWhatsApp = async function(tabId) {
  const reportSettings = state.accountReports[tabId];
  if (!reportSettings || !reportSettings.data || reportSettings.data.length === 0) {
    showToast("يرجى إجراء الاستعلام أولاً قبل محاولة إرسال الواتساب.", "warning");
    return;
  }

  const phoneInput = prompt("أدخل رقم الواتساب لإرسال تقرير الحسابات كـ PDF (صيغة دولية بدون 00 أو + مثل 967777777777):");
  if (phoneInput === null) return;

  const cleanPhone = phoneInput.replace(/[^0-9]/g, '');
  if (!cleanPhone || cleanPhone.length < 8) {
    showToast("رقم الواتساب غير صالح.", "error");
    return;
  }

  showToast("جاري تجهيز التقرير وإرساله بالواتساب كـ PDF...", "info");

  try {
    const res = await fetch('/api/accounts-reports/send-whatsapp-pdf', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        reportType: reportSettings.reportType,
        branchNo: reportSettings.branchId ? parseInt(reportSettings.branchId) : null,
        startDate: reportSettings.startDate || null,
        endDate: reportSettings.endDate || null,
        currencyId: reportSettings.currencyId ? parseInt(reportSettings.currencyId) : null,
        costCenterId: reportSettings.costCenterId ? parseInt(reportSettings.costCenterId) : null,
        groupId: reportSettings.groupId ? parseInt(reportSettings.groupId) : null,
        accType: reportSettings.accType ? parseInt(reportSettings.accType) : null,
        detailType: reportSettings.detailType || 'detailed',
        phone: cleanPhone
      })
    });
    const result = await res.json();
    if (result.success) {
      showToast(result.message || "تم إرسال التقرير بالواتساب بنجاح!", "success");
    } else {
      showToast("خطأ أثناء إرسال الواتساب: " + (result.error || "فشل العملية"), "error");
    }
  } catch (err) {
    console.error("Error in WhatsApp send:", err);
    showToast("حدث خطأ أثناء الاتصال بالخادم لإرسال الواتساب.", "error");
  }
};




window.initItemsExplorerTab = async function(tabId) {
  try {
    if (!state.itemsExplorer) {
      state.itemsExplorer = {};
    }
    state.itemsExplorer[tabId] = {
      itemsList: [],
      selectedItemId: null
    };

    await loadExplorerItems(tabId);
  } catch (err) {
    console.error("Error in initItemsExplorerTab:", err);
  }
};

async function loadExplorerItems(tabId) {
  try {
    const res = await fetch('/api/items');
    const result = await res.json();
    const items = result.data || [];
    state.itemsExplorer[tabId].itemsList = items;
    state.itemsExplorer[tabId].selectedItemId = null;
    
    renderExplorerRows(tabId, items);
  } catch (err) {
    console.error(err);
    showToast("خطأ عند تحميل قائمة الأصناف", "error");
  }
}

function renderExplorerRows(tabId, list) {
  const tbody = document.getElementById(`explorerTableBody-${tabId}`);
  if (!tbody) return;

  if (list.length === 0) {
    tbody.innerHTML = `<tr><td colspan="8" style="text-align: center; padding: 25px; color: #a0aec0;">لا توجد أصناف مطابقة للبحث.</td></tr>`;
    return;
  }

  tbody.innerHTML = list.map(item => {
    const isActiveChecked = item.fldIsActive ? 'checked' : '';
    const currencyName = "ريال سعودي";
    return `
      <tr style="cursor: pointer; transition: background-color var(--transition-fast);" onclick="selectExplorerRow('${tabId}', this, ${item.fldID})" ondblclick="openNewItemModal('${tabId}', ${item.fldID})">
        <td style="padding: 8px; border: 1px solid #cbd5e1; text-align: center;">
          <input type="checkbox" ${isActiveChecked} disabled style="width: 15px; height: 15px;">
        </td>
        <td style="padding: 8px; border: 1px solid #cbd5e1; text-align: right;">${item.fldName2 || ''}</td>
        <td style="padding: 8px; border: 1px solid #cbd5e1; text-align: right;">${item.SupplierName || 'مورد عام'}</td>
        <td style="padding: 8px; border: 1px solid #cbd5e1; text-align: right;">${item.GroupName || 'مجموعة عامة'}</td>
        <td style="padding: 8px; border: 1px solid #cbd5e1; text-align: right;">${item.fldDescription || ''}</td>
        <td style="padding: 8px; border: 1px solid #cbd5e1; text-align: right; font-weight: bold;">${item.fldName}</td>
        <td style="padding: 8px; border: 1px solid #cbd5e1; text-align: center; font-family: monospace;">${item.fldCode}</td>
        <td style="padding: 8px; border: 1px solid #cbd5e1; text-align: center;">${currencyName}</td>
      </tr>
    `;
  }).join('');
}

window.selectExplorerRow = function(tabId, element, id) {
  document.querySelectorAll(`#explorerTableBody-${tabId} tr`).forEach(tr => {
    tr.style.backgroundColor = '';
    tr.style.color = '';
  });
  element.style.backgroundColor = 'var(--primary)';
  element.style.color = '#ffffff';
  state.itemsExplorer[tabId].selectedItemId = id;
};

// Toolbar Handlers
window.explorerNewItem = function(tabId) {
  openNewItemModal(tabId);
};

window.onItemFormGroupChange = async function(groupId, tabId) {
  if (!groupId) return;
  try {
    const res = await fetch(`/api/items/next-code?groupId=${groupId}`);
    const data = await res.json();
    if (data.success && data.nextCode) {
      const codeInput = document.getElementById('newItemCode');
      if (codeInput) codeInput.value = data.nextCode;
    }
  } catch (e) {
    console.error("Error fetching group next code:", e);
  }
};

window.renderItemModalUnitsTable = function(tabId) {
  const tbody = document.getElementById(`newItemUnitsTbody-${tabId}`);
  if (!tbody) return;
  const units = state.newItemUnits || [];

  if (units.length === 0) {
    tbody.innerHTML = `<tr><td colspan="11" style="padding: 15px; color: #94a3b8; text-align: center;">اضغط على "إضافة عبوه" لإضافة العبوات لجدول tblItemsUnit</td></tr>`;
    return;
  }

  tbody.innerHTML = units.map((u, idx) => `
    <tr style="border-bottom: 1px solid #cbd5e1;">
      <td style="padding: 4px; border: 1px solid #cbd5e1;">
        <input type="text" value="${u.fldUnitName || 'حبه'}" onchange="updateItemModalUnitField('${tabId}', ${idx}, 'fldUnitName', this.value)" style="width: 100%; border: none; background: transparent; text-align: center; font-size: 0.75rem;">
      </td>
      <td style="padding: 4px; border: 1px solid #cbd5e1;">
        <input type="number" value="${u.fldQuantity !== undefined ? u.fldQuantity : 1}" onchange="updateItemModalUnitField('${tabId}', ${idx}, 'fldQuantity', parseFloat(this.value)||1)" style="width: 100%; border: none; background: transparent; text-align: center; font-family: monospace; font-size: 0.75rem;">
      </td>
      <td style="padding: 4px; border: 1px solid #cbd5e1;">
        <select onchange="updateItemModalUnitField('${tabId}', ${idx}, 'fldTypeOperation', parseInt(this.value))" style="width: 100%; border: none; background: transparent; text-align: center; font-size: 0.75rem; font-weight: bold;">
          <option value="1" ${(u.fldTypeOperation == 1 || !u.fldTypeOperation) ? 'selected' : ''}>1 (ضرب *)</option>
          <option value="2" ${u.fldTypeOperation == 2 ? 'selected' : ''}>2 (قسمة /)</option>
        </select>
      </td>
      <td style="padding: 4px; border: 1px solid #cbd5e1;">
        <input type="number" value="${u.fldSalesLevel !== undefined ? u.fldSalesLevel : 1}" onchange="updateItemModalUnitField('${tabId}', ${idx}, 'fldSalesLevel', parseInt(this.value)||1)" style="width: 100%; border: none; background: transparent; text-align: center; font-family: monospace; font-size: 0.75rem;">
      </td>
      <td style="padding: 4px; border: 1px solid #cbd5e1;">
        <input type="number" step="0.01" value="${u.fldSalesPrice1 !== undefined ? u.fldSalesPrice1 : 0}" onchange="updateItemModalUnitField('${tabId}', ${idx}, 'fldSalesPrice1', parseFloat(this.value)||0)" style="width: 100%; border: none; background: transparent; text-align: center; font-family: monospace; font-size: 0.75rem;">
      </td>
      <td style="padding: 4px; border: 1px solid #cbd5e1;">
        <input type="number" step="0.01" value="${u.fldSalesPrice2 !== undefined ? u.fldSalesPrice2 : 0}" onchange="updateItemModalUnitField('${tabId}', ${idx}, 'fldSalesPrice2', parseFloat(this.value)||0)" style="width: 100%; border: none; background: transparent; text-align: center; font-family: monospace; font-size: 0.75rem;">
      </td>
      <td style="padding: 4px; border: 1px solid #cbd5e1;">
        <input type="number" step="0.01" value="${u.fldSalesPrice3 !== undefined ? u.fldSalesPrice3 : 0}" onchange="updateItemModalUnitField('${tabId}', ${idx}, 'fldSalesPrice3', parseFloat(this.value)||0)" style="width: 100%; border: none; background: transparent; text-align: center; font-family: monospace; font-size: 0.75rem;">
      </td>
      <td style="padding: 4px; border: 1px solid #cbd5e1;">
        <input type="number" step="0.01" value="${u.fldMinPrice !== undefined ? u.fldMinPrice : 0}" onchange="updateItemModalUnitField('${tabId}', ${idx}, 'fldMinPrice', parseFloat(this.value)||0)" style="width: 100%; border: none; background: transparent; text-align: center; font-family: monospace; font-size: 0.75rem;">
      </td>
      <td style="padding: 4px; border: 1px solid #cbd5e1;">
        <input type="number" step="0.01" value="${u.fldCost !== undefined ? u.fldCost : 0}" onchange="updateItemModalUnitField('${tabId}', ${idx}, 'fldCost', parseFloat(this.value)||0)" style="width: 100%; border: none; background: transparent; text-align: center; font-family: monospace; font-size: 0.75rem;">
      </td>
      <td style="padding: 4px; border: 1px solid #cbd5e1;">
        <input type="number" step="0.01" value="${u.fldcamition !== undefined ? u.fldcamition : 0}" onchange="updateItemModalUnitField('${tabId}', ${idx}, 'fldcamition', parseFloat(this.value)||0)" style="width: 100%; border: none; background: transparent; text-align: center; font-family: monospace; font-size: 0.75rem;">
      </td>
      <td style="padding: 4px; border: 1px solid #cbd5e1;">
        <button type="button" onclick="removeItemModalUnitRow('${tabId}', ${idx})" style="background: none; border: none; color: #ef4444; cursor: pointer; font-size: 0.9rem;" title="حذف العبوة">&times;</button>
      </td>
    </tr>
  `).join('');
};

window.addItemModalUnitRow = function(tabId) {
  if (!state.newItemUnits) state.newItemUnits = [];
  const defaultNames = ['حبه', 'كرتون', 'درزن', 'باكيت', 'شدة'];
  const nextName = defaultNames[state.newItemUnits.length] || 'عبوة';
  state.newItemUnits.push({
    fldUnitName: nextName,
    fldQuantity: state.newItemUnits.length === 1 ? 12 : 1,
    fldTypeOperation: 1,
    fldSalesLevel: 1,
    fldSalesPrice1: 0,
    fldSalesPrice2: 0,
    fldSalesPrice3: 0,
    fldMinPrice: 0,
    fldCost: 0,
    fldcamition: 0
  });
  renderItemModalUnitsTable(tabId);
};

window.removeItemModalUnitRow = function(tabId, idx) {
  if (!state.newItemUnits) return;
  state.newItemUnits.splice(idx, 1);
  renderItemModalUnitsTable(tabId);
};

window.updateItemModalUnitField = function(tabId, idx, field, val) {
  if (!state.newItemUnits || !state.newItemUnits[idx]) return;
  state.newItemUnits[idx][field] = val;
};

window.openNewItemModal = async function(tabId, itemId = null) {
  try {
    const isEdit = !!itemId;
    const modalId = 'newItemModalOverlay';
    const existing = document.getElementById(modalId);
    if (existing) existing.remove();

    let groups = [];
    let suppliers = [];
    let currencies = [];

    try {
      const gRes = await fetch('/api/item-groups');
      const gData = await gRes.json();
      groups = gData.data || [];
    } catch(e) {}

    try {
      const sRes = await fetch('/api/suppliers');
      const sData = await sRes.json();
      suppliers = sData.data || [];
    } catch(e) {}

    try {
      const cRes = await fetch('/api/currencies');
      const cData = await cRes.json();
      currencies = cData.data || [];
    } catch(e) {}

    const groupsOptions = groups.length > 0
      ? groups.map(g => `<option value="${g.fldID}">${g.fldName || g.fldCode}</option>`).join('')
      : `<option value="1">مجموعة عامة</option><option value="2">مجموعة متخصصة</option>`;

    const suppliersOptions = suppliers.length > 0
      ? suppliers.map(s => `<option value="${s.fldID}">${s.fldName || s.fldNo}</option>`).join('')
      : `<option value="3">مكتب الصين</option><option value="4">مورد تجريبي</option>`;

    const currencyOptions = currencies.length > 0
      ? currencies.map(c => `<option value="${c.fldID}">${c.fldName || 'ريال سعودي'}</option>`).join('')
      : `<option value="1">ريال سعودي</option><option value="2">دولار أمريكي</option>`;

    let itemData = null;
    let unitsData = [];
    let defaultGroupId = groups.length > 0 ? groups[0].fldID : 1;
    let nextCode = "1000001";

    if (isEdit) {
      if (state.itemsExplorer && state.itemsExplorer[tabId]) {
        itemData = state.itemsExplorer[tabId].itemsList.find(i => i.fldID === itemId);
      }
      try {
        const itemRes = await fetch(`/api/items/${itemId}`);
        const itemJson = await itemRes.json();
        if (itemJson.success && itemJson.item) {
          itemData = itemJson.item;
          unitsData = itemJson.units || [];
        }
      } catch(e) {}
    } else {
      try {
        const cRes = await fetch(`/api/items/next-code?groupId=${defaultGroupId}`);
        const cData = await cRes.json();
        if (cData.success && cData.nextCode) nextCode = cData.nextCode;
      } catch (e) {}
    }

    const codeVal = isEdit ? (itemData?.fldCode || '') : nextCode;
    const nameVal = isEdit ? (itemData?.fldName || '') : '';
    const descVal = isEdit ? (itemData?.fldDescription || '') : '';
    const groupVal = isEdit ? (itemData?.fldGroupID || defaultGroupId) : defaultGroupId;
    const supplierVal = isEdit ? (itemData?.fldCustomerID || 3) : 3;
    const typeVal = isEdit ? (itemData?.fldTypeItmes || 1) : 1;
    const minQtyVal = isEdit ? (itemData?.fldMinQTY !== undefined ? itemData.fldMinQTY : 0) : 0;
    const maxQtyVal = isEdit ? (itemData?.fldMaxQTY !== undefined ? itemData.fldMaxQTY : 0) : 0;
    const isActiveVal = isEdit ? !!itemData?.fldIsActive : true;
    const isExpVal = isEdit ? !!itemData?.fldExpDate : false;
    const isFreeVal = isEdit ? !!itemData?.fldFreeQTY : false;
    const isSnVal = isEdit ? !!itemData?.fldSerialNumber : false;
    const taxVal = isEdit ? (itemData?.fldlTax !== undefined ? itemData.fldlTax : 15.00) : 15.00;

    // Load initial units
    if (isEdit && unitsData.length > 0) {
      state.newItemUnits = unitsData.map(u => ({
        fldUnitName: u.fldUnitName || 'حبه',
        fldQuantity: u.fldQuantity !== undefined ? u.fldQuantity : 1,
        fldTypeOperation: u.fldTypeOperation !== undefined ? u.fldTypeOperation : 1,
        fldSalesLevel: u.fldSalesLevel !== undefined ? u.fldSalesLevel : 1,
        fldSalesPrice1: u.fldSalesPrice1 !== undefined ? u.fldSalesPrice1 : 0,
        fldSalesPrice2: u.fldSalesPrice2 !== undefined ? u.fldSalesPrice2 : 0,
        fldSalesPrice3: u.fldSalesPrice3 !== undefined ? u.fldSalesPrice3 : 0,
        fldMinPrice: u.fldMinPrice !== undefined ? u.fldMinPrice : 0,
        fldCost: u.fldCost !== undefined ? u.fldCost : 0,
        fldcamition: u.fldcamition !== undefined ? u.fldcamition : 0
      }));
    } else {
      state.newItemUnits = [
        {
          fldUnitName: 'حبه',
          fldQuantity: 1,
          fldTypeOperation: 1,
          fldSalesLevel: 1,
          fldSalesPrice1: 0,
          fldSalesPrice2: 0,
          fldSalesPrice3: 0,
          fldMinPrice: 0,
          fldCost: 0,
          fldcamition: 0
        }
      ];
    }

    const modalHtml = `
      <div class="modal-overlay open" id="${modalId}" style="display: flex; align-items: center; justify-content: center; z-index: 1095; position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0, 0, 0, 0.45); backdrop-filter: blur(2px);">
        <div class="modal-container modal-xl" style="max-width: 1250px; width: 96%; max-height: 94vh; overflow-y: auto; background: #eef2f6; border-radius: 8px; box-shadow: var(--shadow-lg); display: flex; flex-direction: column; direction: rtl; font-family: var(--font-arabic);">
          
          <!-- Top Header Bar -->
          <div style="background-color: #cbd5e1; border-bottom: 2px solid #94a3b8; color: #1e293b; padding: 8px 15px; display: flex; align-items: center; justify-content: space-between;">
            <h2 style="margin: 0; font-size: 1.1rem; display: flex; align-items: center; gap: 8px; color: #1e293b;">
              <i class="fa-solid fa-boxes-packing" style="color: #475569;"></i> ${isEdit ? `تعديل بيانات الصنف (${codeVal})` : 'شاشة إدخال الأصناف'}
            </h2>
            <button style="color: #1e293b; font-size: 1.5rem; border: none; background: none; cursor: pointer; font-weight: bold;" onclick="document.getElementById('${modalId}').remove()">&times;</button>
          </div>

          <!-- Main Content Grid matching Image 1 -->
          <div style="padding: 15px; display: grid; grid-template-columns: 8fr 4fr; gap: 15px;">
            
            <!-- Right Column: Main Form & Units Table -->
            <div style="display: flex; flex-direction: column; gap: 12px;">
              
              <!-- Main Info Form Card -->
              <div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 12px; display: flex; flex-direction: column; gap: 8px;">
                
                <!-- Row 1: المجموعه + رقم الصنف -->
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; align-items: center;">
                  <div style="display: flex; align-items: center; gap: 6px;">
                    <span style="font-weight: bold; font-size: 0.85rem; width: 80px; text-align: left;">المجموعه</span>
                    <div style="display: flex; flex: 1; align-items: center; gap: 4px;">
                      <select id="newItemGroup" onchange="onItemFormGroupChange(this.value, '${tabId}')" style="flex: 1; padding: 5px; border: 1px solid #cbd5e1; border-radius: 4px; font-size: 0.85rem;">
                        ${groupsOptions}
                      </select>
                      <button type="button" class="btn btn-sm btn-primary" onclick="openNewGroupModalFromItemForm('${tabId}')" title="إضافة مجموعة جديدة (tblItemGroup)" style="padding: 4px 8px; font-size: 0.85rem; border-radius: 4px;">
                        <i class="fa-solid fa-circle-plus"></i>
                      </button>
                    </div>
                  </div>

                  <div style="display: flex; align-items: center; gap: 6px;">
                    <span style="font-weight: bold; font-size: 0.85rem; width: 80px; text-align: left;">رقم الصنف</span>
                    <input type="text" id="newItemCode" value="${codeVal}" required style="flex: 1; padding: 5px; border: 1px solid #cbd5e1; border-radius: 4px; font-family: monospace; font-weight: bold; text-align: center;">
                  </div>
                </div>

                <!-- Row 2: الصنف + العمله -->
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; align-items: center;">
                  <div style="display: flex; align-items: center; gap: 6px;">
                    <span style="font-weight: bold; font-size: 0.85rem; width: 80px; text-align: left;">الصنف</span>
                    <input type="text" id="newItemName" value="${nameVal}" required placeholder="اسم الصنف..." style="flex: 1; padding: 5px; border: 1px solid #cbd5e1; border-radius: 4px; font-size: 0.85rem;">
                  </div>

                  <div style="display: flex; align-items: center; gap: 6px;">
                    <span style="font-weight: bold; font-size: 0.85rem; width: 80px; text-align: left;">العمله</span>
                    <div style="display: flex; flex: 1; align-items: center; gap: 4px;">
                      <select id="newItemCurrency" style="flex: 1; padding: 5px; border: 1px solid #cbd5e1; border-radius: 4px; font-size: 0.85rem;">
                        ${currencyOptions}
                      </select>
                      <button type="button" class="btn btn-sm btn-secondary" onclick="openNewCurrencyModal('${tabId}')" title="إضافة عملة جديدة" style="padding: 4px 8px; font-size: 0.85rem; border-radius: 4px;">
                        <i class="fa-solid fa-circle-plus"></i>
                      </button>
                    </div>
                  </div>
                </div>

                <!-- Row 3: الوصف + نوع الصنف -->
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; align-items: center;">
                  <div style="display: flex; align-items: center; gap: 6px;">
                    <span style="font-weight: bold; font-size: 0.85rem; width: 80px; text-align: left;">الوصف</span>
                    <input type="text" id="newItemDescription" value="${descVal}" placeholder="وصف الصنف..." style="flex: 1; padding: 5px; border: 1px solid #cbd5e1; border-radius: 4px; font-size: 0.85rem;">
                  </div>

                  <div style="display: flex; align-items: center; gap: 6px;">
                    <span style="font-weight: bold; font-size: 0.85rem; width: 80px; text-align: left;">نوع الصنف</span>
                    <select id="newItemType" style="flex: 1; padding: 5px; border: 1px solid #cbd5e1; border-radius: 4px; font-size: 0.85rem;">
                      <option value="1" ${typeVal == 1 ? 'selected' : ''}>سلعي</option>
                      <option value="2" ${typeVal == 2 ? 'selected' : ''}>خدمي</option>
                      <option value="3" ${typeVal == 3 ? 'selected' : ''}>تجميعي</option>
                    </select>
                  </div>
                </div>

                <!-- Row 4: المورد -->
                <div style="display: flex; align-items: center; gap: 6px;">
                  <span style="font-weight: bold; font-size: 0.85rem; width: 80px; text-align: left;">المورد</span>
                  <div style="display: flex; flex: 1; align-items: center; gap: 4px;">
                    <select id="newItemSupplier" style="flex: 1; padding: 5px; border: 1px solid #cbd5e1; border-radius: 4px; font-size: 0.85rem;">
                      ${suppliersOptions}
                    </select>
                    <button type="button" class="btn btn-sm btn-primary" onclick="openNewSupplierModalFromItemForm('${tabId}')" title="إضافة مورد جديد (tblCustomer)" style="padding: 4px 8px; font-size: 0.85rem; border-radius: 4px;">
                      <i class="fa-solid fa-circle-plus"></i>
                    </button>
                  </div>
                </div>

              </div>

              <!-- Units Toolbar & Table Container (tblItemsUnit) -->
              <div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 10px; display: flex; flex-direction: column; gap: 10px;">
                
                <div style="display: flex; justify-content: space-between; align-items: center;">
                  <h4 style="margin: 0; font-size: 0.9rem; color: #1e293b; font-weight: bold; display: flex; align-items: center; gap: 6px;">
                    <i class="fa-solid fa-layer-group" style="color: #3b82f6;"></i> جدول العبوات والأسعار (tblItemsUnit)
                  </h4>
                  <div style="display: flex; gap: 8px;">
                    <button type="button" class="btn btn-secondary btn-sm" onclick="addItemModalUnitRow('${tabId}')" style="font-weight: bold; font-size: 0.8rem; padding: 4px 12px; font-family: var(--font-arabic); display: flex; align-items: center; gap: 4px;">
                      <i class="fa-solid fa-plus-circle" style="color: #38a169;"></i> اضافة عبوه
                    </button>
                    <button type="button" class="btn btn-secondary btn-sm" onclick="openUnitArchiveModal('${tabId}')" style="font-weight: bold; font-size: 0.8rem; padding: 4px 12px; font-family: var(--font-arabic); display: flex; align-items: center; gap: 4px;">
                      <i class="fa-solid fa-box-archive" style="color: #4a5568;"></i> الارشيف
                    </button>
                  </div>
                </div>

                <!-- Units Table Grid -->
                <div style="border: 1px solid #cbd5e1; border-radius: 4px; overflow-x: auto; max-height: 220px;">
                  <table style="width: 100%; border-collapse: collapse; font-size: 0.75rem; text-align: center; direction: rtl;">
                    <thead style="background-color: #cbd5e1; border-bottom: 2px solid #94a3b8; position: sticky; top: 0; z-index: 5;">
                      <tr>
                        <th style="padding: 6px; border: 1px solid #cbd5e1; min-width: 90px;">العبوه</th>
                        <th style="padding: 6px; border: 1px solid #cbd5e1; width: 65px;">ك.العبوه</th>
                        <th style="padding: 6px; border: 1px solid #cbd5e1; width: 85px;">العملية (fldTypeOperation)</th>
                        <th style="padding: 6px; border: 1px solid #cbd5e1; width: 85px;">مستوى س البيع</th>
                        <th style="padding: 6px; border: 1px solid #cbd5e1; min-width: 85px;">سعر البيع الاول</th>
                        <th style="padding: 6px; border: 1px solid #cbd5e1; min-width: 85px;">سعر البيع الثاني</th>
                        <th style="padding: 6px; border: 1px solid #cbd5e1; min-width: 85px;">سعر البيع الثالث</th>
                        <th style="padding: 6px; border: 1px solid #cbd5e1; min-width: 85px;">اقل س بيع</th>
                        <th style="padding: 6px; border: 1px solid #cbd5e1; min-width: 85px;">الكلفه</th>
                        <th style="padding: 6px; border: 1px solid #cbd5e1; min-width: 75px;">تسويق</th>
                        <th style="padding: 6px; border: 1px solid #cbd5e1; width: 45px;">حذف</th>
                      </tr>
                    </thead>
                    <tbody id="newItemUnitsTbody-${tabId}">
                      <!-- Rendered dynamically -->
                    </tbody>
                  </table>
                </div>

              </div>

            </div>

            <!-- Left Column: Stock Balances & Controls -->
            <div style="display: flex; flex-direction: column; gap: 12px;">
              
              <!-- Stock / Warehouse Grid -->
              <div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 10px; flex: 1;">
                <h4 style="margin: 0 0 8px 0; font-size: 0.85rem; color: #1e293b; font-weight: bold;">أرصدة المخازن</h4>
                <div style="border: 1px solid #cbd5e1; border-radius: 4px; overflow-x: auto; height: 140px;">
                  <table style="width: 100%; border-collapse: collapse; font-size: 0.75rem; text-align: center;">
                    <thead style="background-color: #cbd5e1;">
                      <tr>
                        <th style="padding: 5px; border: 1px solid #cbd5e1;">السبير</th>
                        <th style="padding: 5px; border: 1px solid #cbd5e1;">الوحده</th>
                        <th style="padding: 5px; border: 1px solid #cbd5e1;">المخزن</th>
                        <th style="padding: 5px; border: 1px solid #cbd5e1;">الكميه</th>
                        <th style="padding: 5px; border: 1px solid #cbd5e1;">السعر</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr>
                        <td style="padding: 5px; border: 1px solid #cbd5e1;">-</td>
                        <td style="padding: 5px; border: 1px solid #cbd5e1;">حبه</td>
                        <td style="padding: 5px; border: 1px solid #cbd5e1;">المخزن الرئيسي</td>
                        <td style="padding: 5px; border: 1px solid #cbd5e1; font-family: monospace;">0</td>
                        <td style="padding: 5px; border: 1px solid #cbd5e1; font-family: monospace;">0.00</td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>

              <!-- Controls: Active, Min/Max Qty, Margin %, Checkboxes, Buttons -->
              <div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 12px; display: flex; flex-direction: column; gap: 8px;">
                
                <div style="display: flex; align-items: center; justify-content: space-between;">
                  <label style="display: flex; align-items: center; gap: 6px; cursor: pointer; font-weight: bold; font-size: 0.8rem;">
                    <input type="checkbox" id="newItemIsActive" ${isActiveVal ? 'checked' : ''} style="width: 16px; height: 16px;">
                    <span>نشط</span>
                  </label>

                  <label style="display: flex; align-items: center; gap: 6px; cursor: pointer; font-weight: bold; font-size: 0.8rem;">
                    <input type="checkbox" id="newItemExpDate" ${isExpVal ? 'checked' : ''} style="width: 16px; height: 16px;">
                    <span>صلاحية (fldExpDate)</span>
                  </label>
                </div>

                <div style="display: flex; align-items: center; justify-content: space-between;">
                  <label style="display: flex; align-items: center; gap: 6px; cursor: pointer; font-weight: bold; font-size: 0.8rem;">
                    <input type="checkbox" id="newItemFreeQTY" ${isFreeVal ? 'checked' : ''} style="width: 16px; height: 16px;">
                    <span>مجاني (fldFreeQTY)</span>
                  </label>

                  <label style="display: flex; align-items: center; gap: 6px; cursor: pointer; font-weight: bold; font-size: 0.8rem;">
                    <input type="checkbox" id="newItemSerialNumber" ${isSnVal ? 'checked' : ''} style="width: 16px; height: 16px;">
                    <span>سيريال (fldSerialNumber)</span>
                  </label>
                </div>

                <div style="display: flex; align-items: center; gap: 8px; justify-content: space-between;">
                  <input type="number" step="0.01" id="newItemTax" value="${taxVal}" style="width: 80px; padding: 4px; border: 1px solid #cbd5e1; border-radius: 4px; text-align: center; font-family: monospace;">
                  <span style="font-size: 0.8rem; font-weight: bold;">نسبة الضريبة (fldlTax) %</span>
                </div>

                <div style="display: flex; align-items: center; gap: 8px; justify-content: space-between;">
                  <input type="number" id="newItemMinQTY" value="${minQtyVal}" style="width: 80px; padding: 4px; border: 1px solid #cbd5e1; border-radius: 4px; text-align: center; font-family: monospace;">
                  <span style="font-size: 0.8rem; font-weight: bold;">الحد الادنى</span>
                </div>

                <div style="display: flex; align-items: center; gap: 8px; justify-content: space-between;">
                  <input type="number" id="newItemMaxQTY" value="${maxQtyVal}" style="width: 80px; padding: 4px; border: 1px solid #cbd5e1; border-radius: 4px; text-align: center; font-family: monospace;">
                  <span style="font-size: 0.8rem; font-weight: bold;">الحد الاعلى</span>
                </div>

                <div style="display: flex; align-items: center; gap: 8px; justify-content: space-between;">
                  <input type="number" step="0.01" id="newItemMarginPercent" value="0.00" style="width: 80px; padding: 4px; border: 1px solid #cbd5e1; border-radius: 4px; text-align: center; font-family: monospace;">
                  <span style="font-size: 0.8rem; font-weight: bold;">نسبة سعر البيع %</span>
                </div>

                <div style="display: flex; gap: 8px; margin-top: 6px; justify-content: space-between;">
                  <button type="button" class="btn btn-secondary btn-sm" onclick="openBarcodeModal('${tabId}', ${isEdit ? itemId : 'null'})" style="flex: 1; font-weight: bold;">الباركود</button>
                  <button type="button" class="btn btn-secondary btn-sm" onclick="renumberExplorerItems('${tabId}')" style="flex: 1; font-weight: bold;">اعادة ترقيم الاصناف</button>
                </div>

              </div>

            </div>

          </div>

          <!-- Bottom Actions Bar -->
          <div style="background-color: #f1f5f9; padding: 10px 15px; border-top: 1px solid #cbd5e1; display: flex; justify-content: flex-end; gap: 12px; border-radius: 0 0 8px 8px;">
            <button type="button" class="btn btn-primary" onclick="saveNewItemForm(event, '${tabId}', ${isEdit ? itemId : 'null'})" style="padding: 8px 25px; font-weight: bold; font-size: 0.9rem; display: flex; align-items: center; gap: 6px;">
              <i class="fa-solid fa-floppy-disk"></i> ${isEdit ? 'حفظ التعديلات' : 'حفظ الصنف'}
            </button>
            <button type="button" class="btn btn-secondary" onclick="document.getElementById('${modalId}').remove()" style="padding: 8px 20px; font-size: 0.9rem;">
              إلغاء
            </button>
          </div>

        </div>
      </div>
    `;

    document.body.insertAdjacentHTML('beforeend', modalHtml);

    if (isEdit) {
      const gSel = document.getElementById('newItemGroup');
      if (gSel) gSel.value = groupVal;
      const sSel = document.getElementById('newItemSupplier');
      if (sSel) sSel.value = supplierVal;
    }

    renderItemModalUnitsTable(tabId);

    // Focus on first field (المجموعة)
    const firstGroupField = document.getElementById('newItemGroup');
    if (firstGroupField) firstGroupField.focus();

    // Enable Enter key navigation through all form fields
    setupItemModalEnterNavigation(modalId, tabId, itemId);

  } catch (err) {
    console.error("Error opening new item modal:", err);
    showToast("خطأ أثناء فتح نافذة إضافة/تعديل الصنف.", "error");
  }
};

