window.saveQuickGroupFromForm = async function(tabId) {
  const code = document.getElementById('quickGroupCode').value.trim();
  const name = document.getElementById('quickGroupName').value.trim();
  const rate = document.getElementById('quickGroupRate').value || 0;

  if (!name || !code) {
    showToast("يرجى إدخال اسم ورقم المجموعة.", "warning");
    return;
  }

  try {
    showToast("جاري حفظ المجموعة...", "info");
    const r = await fetch('/api/item-groups', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, code, rate })
    });
    const resObj = await r.json();
    if (resObj.success) {
      showToast("تم إضافة المجموعة بنجاح!", "success");
      document.getElementById('groupCreateModalOverlay')?.remove();

      const gRes = await fetch('/api/item-groups');
      const gData = await gRes.json();
      const groups = gData.data || [];
      const select = document.getElementById('newItemGroup');
      if (select) {
        select.innerHTML = groups.map(g => `<option value="${g.fldID}">${g.fldName || g.fldCode}</option>`).join('');
        const addedId = resObj.group ? resObj.group.fldID : (groups.length > 0 ? groups[groups.length-1].fldID : null);
        if (addedId) {
          select.value = addedId;
          onItemFormGroupChange(addedId, tabId);
        }
      }
    } else {
      showToast("فشل حفظ المجموعة: " + resObj.error, "error");
    }
  } catch(e) {
    console.error(e);
    showToast("خطأ عند حفظ المجموعة.", "error");
  }
};

