window.exportCurrentTabTable = function(tabId, defaultName = 'تقرير') {
  const container = document.getElementById(`tab-content-${tabId}`) || document.getElementById(tabId) || document;
  const table = container.querySelector('table');
  if (!table) {
    showToast('لا يوجد جدول بيانات للتصدير في هذه الشاشة.', 'warning');
    return;
  }
  
  const clone = table.cloneNode(true);
  clone.querySelectorAll('.no-print, button, input[type="checkbox"]').forEach(el => el.remove());

  const html = `
    <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
    <head>
      <meta charset="utf-8" />
      <style>
        table { border-collapse: collapse; width: 100%; direction: rtl; }
        th, td { border: 1px solid #cbd5e1; padding: 8px; text-align: center; font-family: Tahoma, Arial, sans-serif; }
        th { background-color: #1e3a8a; color: #ffffff; font-weight: bold; }
      </style>
    </head>
    <body>
      ${clone.outerHTML}
    </body>
    </html>
  `;

  const blob = new Blob(['\ufeff', html], { type: 'application/vnd.ms-excel;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  const dateStr = new Date().toISOString().slice(0, 10);
  a.download = `${defaultName}_${dateStr}.xls`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast('تم تصدير البيانات إلى ملف Excel بنجاح.', 'success');
};

