window.filterExplorerTable = function(tabId) {
  const nVal = document.getElementById(`filterNotes-${tabId}`)?.value.toLowerCase().trim() || '';
  const supVal = document.getElementById(`filterSupplier-${tabId}`)?.value.toLowerCase().trim() || '';
  const gVal = document.getElementById(`filterGroup-${tabId}`)?.value.toLowerCase().trim() || '';
  const dVal = document.getElementById(`filterDesc-${tabId}`)?.value.toLowerCase().trim() || '';
  const nameVal = document.getElementById(`filterName-${tabId}`)?.value.toLowerCase().trim() || '';
  const codeVal = document.getElementById(`filterCode-${tabId}`)?.value.toLowerCase().trim() || '';
  const curVal = document.getElementById(`filterCurrency-${tabId}`)?.value.toLowerCase().trim() || '';

  const itemsList = state.itemsExplorer[tabId]?.itemsList || [];
  const filtered = itemsList.filter(item => {
    return (
      (item.fldName2 || '').toLowerCase().includes(nVal) &&
      (item.SupplierName || 'مورد عام').toLowerCase().includes(supVal) &&
      (item.GroupName || 'مجموعة عامة').toLowerCase().includes(gVal) &&
      (item.fldDescription || '').toLowerCase().includes(dVal) &&
      (item.fldName || '').toLowerCase().includes(nameVal) &&
      (item.fldCode || '').toLowerCase().includes(codeVal) &&
      ("ريال سعودي".includes(curVal) || curVal === "")
    );
  });

  renderExplorerRows(tabId, filtered);
};

