window.switchPosPurchasesSubTab = function(subTab) {
  posState.activePurchasesSubTab = subTab;
  const btnInvoices = document.getElementById('subpill-purchases-invoices');
  const btnStock = document.getElementById('subpill-purchases-stock');
  const boxInvoices = document.getElementById('posPurchasesInvoicesBox');
  const boxStock = document.getElementById('posPurchasesStockBox');

  if (subTab === 'stock') {
    if (btnInvoices) btnInvoices.classList.remove('active');
    if (btnStock) btnStock.classList.add('active');
    if (boxInvoices) boxInvoices.style.display = 'none';
    if (boxStock) boxStock.style.display = 'block';
    window.fetchPosInventory();
  } else {
    if (btnInvoices) btnInvoices.classList.add('active');
    if (btnStock) btnStock.classList.remove('active');
    if (boxInvoices) boxInvoices.style.display = 'block';
    if (boxStock) boxStock.style.display = 'none';
  }
};

