// 13. عرض التقرير الختامي
window.renderPosSummaryReport = function(s, currencies = []) {
  const salesElem = document.getElementById('sumRptSales');
  const returnsElem = document.getElementById('sumRptReturns');
  const netSalesElem = document.getElementById('sumRptNetSales');
  const purchasesElem = document.getElementById('sumRptPurchases');
  const receiptsElem = document.getElementById('sumRptReceipts');
  const expensesElem = document.getElementById('sumRptExpenses');
  const balanceElem = document.getElementById('sumRptCashBalance');

  const baseSymbol = s.currencySymbol || s.baseCurrencySymbol || 'د.أ';

  if (salesElem) salesElem.innerHTML = formatPosCardCurrencies('salesTotal', currencies, s.totalSales, baseSymbol);
  if (returnsElem) returnsElem.innerHTML = formatPosCardCurrencies('returnsTotal', currencies, s.totalReturns, baseSymbol);
  
  const netSales = (s.totalSales || 0) - (s.totalReturns || 0);
  if (netSalesElem) netSalesElem.innerHTML = formatPosCardCurrencies('netSales', currencies, netSales, baseSymbol);

  if (purchasesElem) purchasesElem.innerHTML = formatPosCardCurrencies('purchasesTotal', currencies, s.totalPurchases, baseSymbol);
  if (receiptsElem) receiptsElem.innerHTML = formatPosCardCurrencies('receiptsTotal', currencies, s.totalReceipts, baseSymbol);
  if (expensesElem) expensesElem.innerHTML = formatPosCardCurrencies('expensesTotal', currencies, s.totalExpenses, baseSymbol);
  if (balanceElem) balanceElem.innerHTML = formatPosCardCurrencies('actualCashBalance', currencies, s.actualCashBalance, baseSymbol);
};

// 14. حاسبة تسوية وردية الصندوق والإغلاق اليومي (Shift Cash Drawer Settlement Calculator)
window.calculatePosShiftSettlement = function() {
  const s = posState.dashboardData?.summary || {};
  const netCashIncome = (s.cashSales || 0) + (s.totalReceipts || 0) - (s.totalExpenses || 0) - (s.returnsCash || 0);
  const openingFloat = parseFloat(document.getElementById('posCalcOpeningFloat')?.value) || 0;
  const expectedTotal = openingFloat + netCashIncome;

  const netCashEl = document.getElementById('posCalcNetCashIncome');
  const expectedEl = document.getElementById('posCalcExpectedDrawerCash');
  if (netCashEl) netCashEl.textContent = `${netCashIncome.toFixed(2)} د.أ`;
  if (expectedEl) expectedEl.textContent = `${expectedTotal.toFixed(2)} د.أ`;

  const actualInput = document.getElementById('posCalcActualCountedCash');
  const resultBox = document.getElementById('posSettlementResultBox');
  const titleEl = document.getElementById('posSettlementDiffTitle');
  const diffValEl = document.getElementById('posSettlementDiffVal');
  const diffSubEl = document.getElementById('posSettlementDiffSub');

  if (!actualInput || !actualInput.value.trim()) {
    if (resultBox) resultBox.className = 'pos-settlement-result-box';
    if (titleEl) titleEl.textContent = 'حالة تسوية الوردية: بانتظار العد الفعلي';
    if (diffValEl) diffValEl.textContent = '0.00 د.أ';
    if (diffSubEl) diffSubEl.textContent = 'أدخل النقدية الفعلية لحساب العجز أو الفائض';
    return;
  }

  const actualCash = parseFloat(actualInput.value) || 0;
  const diff = actualCash - expectedTotal;

  if (Math.abs(diff) < 0.01) {
    if (resultBox) resultBox.className = 'pos-settlement-result-box balanced';
    if (titleEl) titleEl.textContent = '✅ الصندوق متطابق تماماً (Balanced Shift)';
    if (diffValEl) diffValEl.textContent = '0.00 د.أ';
    if (diffSubEl) diffSubEl.textContent = 'النقدية الفعلية مطابقة للرصيد الدفتري 100%';
  } else if (diff > 0) {
    if (resultBox) resultBox.className = 'pos-settlement-result-box surplus';
    if (titleEl) titleEl.textContent = '🟢 يوجد فائض في الصندوق (Cash Surplus)';
    if (diffValEl) diffValEl.textContent = `+${diff.toFixed(2)} د.أ`;
    if (diffSubEl) diffSubEl.textContent = `المبلغ الفعلي أكبر من الرصيد الدفتري بمقدار ${diff.toFixed(2)} د.أ`;
  } else {
    if (resultBox) resultBox.className = 'pos-settlement-result-box shortage';
    if (titleEl) titleEl.textContent = '🔴 يوجد عجز في الصندوق (Cash Shortage)';
    if (diffValEl) diffValEl.textContent = `${diff.toFixed(2)} د.أ`;
    if (diffSubEl) diffSubEl.textContent = `المبلغ الفعلي أقل من الرصيد الدفتري بمقدار ${Math.abs(diff).toFixed(2)} د.أ`;
  }
};

// Print Shift Z-Report
window.printPosShiftZReport = function() {
  const p = posState.selectedPoint;
  const s = posState.dashboardData?.summary || {};
  const openingFloat = parseFloat(document.getElementById('posCalcOpeningFloat')?.value) || 0;
  const actualCash = parseFloat(document.getElementById('posCalcActualCountedCash')?.value) || 0;
  const expectedTotal = openingFloat + (s.cashSales || 0) + (s.totalReceipts || 0) - (s.totalExpenses || 0);
  const diff = actualCash - expectedTotal;

  const html = `
    <html dir="rtl" lang="ar">
    <head>
      <meta charset="utf-8">
      <title>تقرير إغلاق الوردية (Z-Report) - نقطة [${p?.fldPointNO || 31}]</title>
      <style>
        body { font-family: 'Courier New', Courier, monospace, Tahoma; font-size: 13px; margin: 20px; line-height: 1.4; }
        .receipt { max-width: 320px; margin: 0 auto; text-align: center; }
        .divider { border-top: 1px dashed #000; margin: 8px 0; }
        .row { display: flex; justify-content: space-between; margin: 4px 0; }
        .grand { font-weight: bold; font-size: 15px; border-top: 1px dashed #000; border-bottom: 1px dashed #000; padding: 4px 0; }
      </style>
    </head>
    <body onload="window.print()">
      <div class="receipt">
        <h2>تقرير إغلاق الوردية (Z-Report)</h2>
        <p>${p?.fldName || 'نقطة بيع'} - الفرع [${p?.fldBranchNo || 1}]</p>
        <p>التاريخ: ${new Date().toLocaleDateString('ar-EG')} - الوقت: ${new Date().toLocaleTimeString('ar-EG')}</p>
        <div class="divider"></div>
        <div class="row"><span>رصيد الافتتاح:</span><strong>${openingFloat.toFixed(2)} د.أ</strong></div>
        <div class="row"><span>(+) مبيعات نقدية:</span><strong>${(s.cashSales || 0).toFixed(2)} د.أ</strong></div>
        <div class="row"><span>(+) سندات القبض:</span><strong>${(s.totalReceipts || 0).toFixed(2)} د.أ</strong></div>
        <div class="row"><span>(-) سندات الصرف:</span><strong>${(s.totalExpenses || 0).toFixed(2)} د.أ</strong></div>
        <div class="row"><span>(-) مردود المبيعات:</span><strong>${(s.totalReturns || 0).toFixed(2)} د.أ</strong></div>
        <div class="divider"></div>
        <div class="row grand"><span>الرصيد الدفتري المتوقع:</span><span>${expectedTotal.toFixed(2)} د.أ</span></div>
        <div class="row"><span>النقدية الفعلية بالدرج:</span><strong>${actualCash.toFixed(2)} د.أ</strong></div>
        <div class="row grand"><span>الفارق (عجز / فائض):</span><span>${diff.toFixed(2)} د.أ</span></div>
        <div class="divider"></div>
        <p>توقيع الكاشير: _________________</p>
        <p>توقيع المشرف: _________________</p>
      </div>
    </body>
    </html>
  `;

  const printWin = window.open('', '_blank', 'width=450,height=600');
  if (printWin) {
    printWin.document.write(html);
    printWin.document.close();
  }
};

