// 17. جلب مخزون نقطة البيع
window.fetchPosInventory = async function() {
  const pointNo = posState.selectedPoint?.fldPointNO || 31;
  const tbody = document.getElementById('posInventoryTbody');
  if (tbody) tbody.innerHTML = '<tr><td colspan="7" class="text-center text-info"><i class="fa-solid fa-spinner fa-spin"></i> جاري استعلام مخزون نقطة البيع...</td></tr>';

  try {
    const res = await fetch(`/api/pos/inventory?pointNo=${pointNo}&storeId=${posState.selectedPoint?.fldstoreID || 1}`);
    const data = await res.json();

    if (data.success && data.inventory) {
      posState.inventory = data.inventory;
      if (data.inventory.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" class="text-center text-muted" style="padding: 25px;">لا توجد أصناف في مخزون هذه النقطة</td></tr>';
        return;
      }

      tbody.innerHTML = '';
      data.inventory.forEach(item => {
        const qty = parseFloat(item.fldQuantity) || 0;
        const isLow = qty <= 2;
        const tr = document.createElement('tr');
        tr.innerHTML = `
          <td><code>${item.fldBarCode || '---'}</code></td>
          <td style="font-weight: bold; color: #f8fafc;">${item.fldItemName || 'صنف'}</td>
          <td>${item.fldUnitName || 'حبة'}</td>
          <td style="font-family: monospace;">${parseFloat(item.fldSalesPrice || 0).toFixed(2)}</td>
          <td style="font-family: monospace;">${parseFloat(item.fldCost || 0).toFixed(2)}</td>
          <td><span class="pay-pill ${isLow ? 'pay-credit' : 'pay-cash'}">${qty}</span></td>
          <td>${isLow ? '<span style="color:#f87171; font-weight:bold;">⚠️ رصيد منخفض</span>' : '<span style="color:#34d399;">متوفر</span>'}</td>
        `;
        tbody.appendChild(tr);
      });
    } else {
      if (tbody) tbody.innerHTML = `<tr><td colspan="7" class="text-center text-danger">${data.error || 'فشل استعلام المخزون'}</td></tr>`;
    }
  } catch (err) {
    console.error("Error fetching POS inventory:", err);
  }
};

window.exportPosInventoryToExcel = function() {
  const items = posState.inventory || [];
  if (items.length === 0) {
    if (typeof showToast === 'function') showToast("لا توجد بيانات مخزون لتصديرها.", "warning");
    return;
  }
  let csv = "\uFEFFالباركود;اسم الصنف;الوحدة;سعر البيع;سعر التكلفة;الكمية المتاحة\n";
  items.forEach(i => {
    csv += `"${i.fldBarCode || ''}";"${i.fldItemName || ''}";"${i.fldUnitName || ''}";${i.fldSalesPrice || 0};${i.fldCost || 0};${i.fldQuantity || 0}\n`;
  });
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `POS_Inventory_Point_${posState.selectedPoint?.fldPointNO || 31}.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
};

// 18. مزامنة وسحب الحركات (Main & Details & Expenses)
window.syncSelectedPosPointData = async function(customPointNo = null) {
  const pointSelect = document.getElementById('posPointSelect');
  const pointNo = customPointNo || (pointSelect ? pointSelect.value : null) || 31;
  const pointName = (pointSelect && pointSelect.options[pointSelect.selectedIndex]) 
    ? pointSelect.options[pointSelect.selectedIndex].text 
    : `نقطة البيع رقم [${pointNo}]`;

  const confirmSync = confirm(`هل ترغب في بدء سحب ومزامنة بيانات وحركات ${pointName} من جداول Main و details و tblExpenses إلى السيرفر الرئيسي؟`);
  if (!confirmSync) return;

  if (typeof showToast === 'function') showToast(`جاري سحب ومزامنة بيانات ${pointName}... يرجى الانتظار`, 'info');

  try {
    const res = await fetch('/api/pos/import-transactions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ pointNo: parseInt(pointNo) })
    });

    const data = await res.json();
    if (data.success) {
      const stats = data.syncedStats || {};
      const msg = `✅ تم سحب ومزامنة بيانات ${pointName} بنجاح!\n(الفواتير: ${stats.mainCount || 0} | التفاصيل: ${stats.detailsCount || 0} | المصروفات: ${stats.expensesCount || 0})`;
      if (typeof showToast === 'function') showToast(msg, 'success');
      window.loadPosOpsDashboard();
    } else {
      if (typeof showToast === 'function') showToast(`فشلت المزامنة: ${data.error || 'خطأ غير متوقع'}`, 'error');
    }
  } catch (err) {
    console.error('Error syncing POS point data:', err);
    if (typeof showToast === 'function') showToast(`حدث خطأ أثناء المزامنة: ${err.message}`, 'error');
  }
};

// 19. تزويد الأصناف والمجموعات والعملات لنقطة البيع
window.syncItemsToSelectedPosPoint = async function(customPointNo = null) {
  const pointSelect = document.getElementById('posPointSelect');
  const pointNo = customPointNo || (pointSelect ? pointSelect.value : null) || 31;
  const pointName = (pointSelect && pointSelect.options[pointSelect.selectedIndex]) 
    ? pointSelect.options[pointSelect.selectedIndex].text 
    : `نقطة البيع رقم [${pointNo}]`;

  const confirmSync = confirm(`هل ترغب في تزويد ومزامنة الأصناف والمجموعات والعملات من السيرفر الرئيسي إلى ${pointName}؟`);
  if (!confirmSync) return;

  if (typeof showToast === 'function') showToast(`جاري تزويد ومزامنة الأصناف والمجموعات والعملات إلى ${pointName}...`, 'info');

  try {
    const res = await fetch('/api/pos/sync-items', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ pointNo: parseInt(pointNo) })
    });

    const data = await res.json();
    if (data.success) {
      const stats = data.syncedStats || {};
      const msg = `✅ تمت مزامنة وتزويد الأصناف بنجاح!\n(الأصناف: ${stats.items || 0} | المجموعات: ${stats.groups || 0} | العملات: ${stats.currencies || 0})`;
      if (typeof showToast === 'function') showToast(msg, 'success');
    } else {
      if (typeof showToast === 'function') showToast(`فشل التزويد: ${data.error || 'خطأ'}`, 'error');
    }
  } catch (err) {
    console.error('Error syncing items to POS:', err);
    if (typeof showToast === 'function') showToast(`حدث خطأ: ${err.message}`, 'error');
  }
};

// 20. ترحيل حركات نقطة البيع للحسابات العامة
window.postSelectedPosTransactions = async function(customPointNo = null, specificTransNumber = null) {
  const pointSelect = document.getElementById('posPointSelect');
  const pointNo = customPointNo || (pointSelect ? pointSelect.value : null) || 31;

  const confirmMsg = specificTransNumber 
    ? `هل ترغب في ترحيل الفاتورة رقم (${specificTransNumber}) لنقطة البيع [${pointNo}] إلى الحسابات والمخازن العامة؟`
    : `هل ترغب في ترحيل كافة حركات نقطة البيع رقم [${pointNo}] غير المرحلة إلى الحسابات والمخازن العامة (قيود يومية + حركة مخازن + حركة نقدية)؟`;

  if (!confirm(confirmMsg)) return;

  if (typeof showToast === 'function') showToast("جاري ترحيل الحركات إلى الحسابات والمخازن...", "info");

  try {
    const res = await fetch('/api/pos/post-transactions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        pointNo: parseInt(pointNo),
        transNumber: specificTransNumber || null
      })
    });

    const data = await res.json();
    if (data.success) {
      const stats = data.stats || {};
      const msg = `✅ تم ترحيل الحركات بنجاح!\n(حركات المبيعات: ${stats.mainPosted || 0} | بنود الأصناف: ${stats.detailsPosted || 0} | حركات الصندوق: ${stats.expensesPosted || 0})`;
      if (typeof showToast === 'function') showToast(msg, 'success');
      window.loadPosOpsDashboard();
    } else {
      if (typeof showToast === 'function') showToast(`فشل الترحيل: ${data.error || 'خطأ'}`, 'error');
    }
  } catch (err) {
    console.error('Error posting POS transactions:', err);
    if (typeof showToast === 'function') showToast(`حدث خطأ: ${err.message}`, 'error');
  }
};

