window.downloadPosDashboardPdf = async function() {
  const pointNo = posState.selectedPoint?.fldPointNO || 31;
  const start = document.getElementById('posOpsStartDate')?.value || '';
  const end = document.getElementById('posOpsEndDate')?.value || '';

  if (typeof showToast === 'function') showToast("جاري توليد ملف PDF للتقرير الشامل...", "info");
  try {
    const res = await fetch('/api/pos/dashboard/download-pdf', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ pointNo, startDate: start, endDate: end })
    });
    if (!res.ok) throw new Error("فشل توليد ملف PDF");
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `POS_Point_${pointNo}_Report.pdf`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    if (typeof showToast === 'function') showToast("تم تحميل تقرير PDF بنجاح!", "success");
  } catch (err) {
    if (typeof showToast === 'function') showToast(`فشل التحميل: ${err.message}`, "error");
  }
};

