window.sendPosSalesWhatsApp = async function() {
  const pointNo = posState.selectedPoint?.fldPointNO || 31;
  const isReturns = posState.activeSalesSubTab === 'returns';
  const start = document.getElementById('posOpsStartDate')?.value || '';
  const end = document.getElementById('posOpsEndDate')?.value || '';

  const phone = prompt(`أدخل رقم الواتساب لإرسال تقرير ${isReturns ? 'المردود' : 'المبيعات'}:`, "");
  if (!phone) return;

  if (typeof showToast === 'function') showToast("جاري إرسال التقرير عبر الواتساب...", "info");
  try {
    const res = await fetch('/api/pos/sales-report/send-whatsapp-pdf', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ pointNo, startDate: start, endDate: end, isReturns, phone })
    });
    const result = await res.json();
    if (result.success) {
      if (typeof showToast === 'function') showToast(result.message || "تم إرسال التقرير بنجاح!", "success");
    } else {
      if (typeof showToast === 'function') showToast(result.error || "تعذر الإرسال", "warning");
    }
  } catch (err) {
    if (typeof showToast === 'function') showToast(`حدث خطأ: ${err.message}`, "error");
  }
};

window.downloadPosExpensesPdf = async function() {
  const pointNo = posState.selectedPoint?.fldPointNO || 31;
  const start = document.getElementById('posOpsStartDate')?.value || '';
  const end = document.getElementById('posOpsEndDate')?.value || '';

  if (typeof showToast === 'function') showToast("جاري إعداد تقرير المصروفات PDF...", "info");
  try {
    const res = await fetch('/api/pos/expenses-report/download-pdf', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ pointNo, startDate: start, endDate: end })
    });
    if (!res.ok) throw new Error("فشل توليد ملف PDF");
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `POS_Expenses_Point_${pointNo}.pdf`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    if (typeof showToast === 'function') showToast("تم تحميل ملف المصروفات بنجاح!", "success");
  } catch (err) {
    if (typeof showToast === 'function') showToast(`فشل التحميل: ${err.message}`, "error");
  }
};

