posState.dailyReportData = { rows: [], summary: {} };

window.setPosDailyRptDateRange = function(rangeType) {
  const startElem = document.getElementById('posDailyRptStartDate');
  const endElem = document.getElementById('posDailyRptEndDate');
  if (!startElem || !endElem) return;

  const now = new Date();
  const formatIso = d => {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  };

  if (rangeType === 'today') {
    startElem.value = formatIso(now);
    endElem.value = formatIso(now);
  } else if (rangeType === 'yesterday') {
    const yest = new Date(now);
    yest.setDate(yest.getDate() - 1);
    startElem.value = formatIso(yest);
    endElem.value = formatIso(yest);
  } else if (rangeType === 'week') {
    const weekAgo = new Date(now);
    weekAgo.setDate(weekAgo.getDate() - 7);
    startElem.value = formatIso(weekAgo);
    endElem.value = formatIso(now);
  } else if (rangeType === 'month') {
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
    startElem.value = formatIso(firstDay);
    endElem.value = formatIso(now);
  } else if (rangeType === 'all') {
    startElem.value = '2026-01-01';
    endElem.value = formatIso(now);
  }

  window.loadPosDailyMovementReport();
};

window.loadPosDailyMovementReport = async function() {
  const startDate = document.getElementById('posDailyRptStartDate')?.value || '2026-08-01';
  const endDate = document.getElementById('posDailyRptEndDate')?.value || '2026-08-21';
  const pointNo = document.getElementById('posDailyRptPointSelect')?.value || '';

  const tbody = document.getElementById('posDailyMovementTableBody');
  const tfoot = document.getElementById('posDailyMovementTableFoot');

  if (tbody) {
    tbody.innerHTML = `
      <tr>
        <td colspan="7" style="padding: 30px; color: #94a3b8; text-align: center;">
          <div class="spinner" style="margin: 0 auto 10px; border-top-color: #38bdf8;"></div>
          جاري تحميل وتجميع حركة نقاط البيع اليومية للفترة [${startDate} إلى ${endDate}]...
        </td>
      </tr>
    `;
  }
  if (tfoot) tfoot.innerHTML = '';

  try {
    const params = new URLSearchParams();
    if (startDate) params.append('startDate', startDate);
    if (endDate) params.append('endDate', endDate);
    if (pointNo) params.append('pointNo', pointNo);

    const res = await fetch(`/api/pos/daily-movement-report?${params.toString()}`);
    const data = await res.json();

    if (data.success && data.rows) {
      posState.dailyReportData = data;
      window.renderPosDailyMovementTable(data.rows, data.summary);
    } else {
      if (tbody) {
        tbody.innerHTML = `<tr><td colspan="7" style="padding: 25px; color: #ef4444; text-align: center;">خطأ: ${data.error || 'فشل تحميل التقرير'}</td></tr>`;
      }
    }
  } catch (err) {
    console.error("Error loading daily movement report:", err);
    if (tbody) {
      tbody.innerHTML = `<tr><td colspan="7" style="padding: 25px; color: #ef4444; text-align: center;">تعذر الاتصال بالسيرفر لجلب التقرير.</td></tr>`;
    }
  }
};

