window.openStoreTransferTab = function(transferId = null) {
  // Check user permission for Store Transfer Menu (28)
  const isAdmin = state.currentUser && (state.currentUser.fldAdmin || state.currentUser.isAdmin || state.currentUser.id === 1);
  if (!isAdmin && state.permissions && state.permissions.length > 0) {
    if (!hasPermission(28, 'fldSELECT')) {
      showToast("عذراً، ليس لديك صلاحية استعلام (عرض) لشاشة التحويل المخزني.", "error");
      return;
    }
  }

  const tabId = transferId ? `store-transfer-${transferId}` : 'store-transfer-new';
  const tabTitle = transferId ? `تحويل مخزني #${transferId}` : 'التحويل المخزني';
  openTab(tabId, tabTitle, 'fa-solid fa-boxes-packing', 'text-primary', true);
  if (transferId) {
    setTimeout(() => {
      if (typeof window.loadTransferDetails === 'function') {
        window.loadTransferDetails(tabId, transferId);
      }
    }, 200);
  }
};

