// Populate Store Transfer Branches & Warehouses
async function populateStoreTransferMetadata(tabId) {
  const sourceBranchSelect = document.getElementById(`stSourceBranch-${tabId}`);
  const targetBranchSelect = document.getElementById(`stTargetBranch-${tabId}`);
  const sourceStoreSelect = document.getElementById(`stSourceWarehouse-${tabId}`);
  const targetStoreSelect = document.getElementById(`stTargetWarehouse-${tabId}`);

  if (sourceBranchSelect && targetBranchSelect) {
    sourceBranchSelect.innerHTML = '';
    targetBranchSelect.innerHTML = '';

    try {
      const res = await fetch('/api/branches');
      const data = await res.json();
      const branches = (data && data.data && data.data.length > 0) ? data.data : (state.branches || [
        { fldID: 1, fldName: "الفرع الرئيسي" },
        { fldID: 3, fldName: "الاميرة 1" }
      ]);

      branches.forEach(b => {
        sourceBranchSelect.innerHTML += `<option value="${b.fldID}">${b.fldName}</option>`;
        targetBranchSelect.innerHTML += `<option value="${b.fldID}">${b.fldName}</option>`;
      });

      if (branches.length > 1) targetBranchSelect.selectedIndex = 1;
    } catch(e) {
      console.error("Error loading branches from dbo.tblBranchList:", e);
    }
  }

  // Populate Stores (tblStore)
  if (sourceStoreSelect && targetStoreSelect) {
    sourceStoreSelect.innerHTML = '';
    targetStoreSelect.innerHTML = '';

    try {
      const res = await fetch('/api/stores');
      const data = await res.json();
      let stores = (data.success && data.stores) ? data.stores : [
        { fldID: 1, fldName: "المستودع العام1" },
        { fldID: 2, fldName: "مستودع المعلا" },
        { fldID: 3, fldName: "مستودع التواهي" }
      ];

      stores.forEach(s => {
        sourceStoreSelect.innerHTML += `<option value="${s.fldID}">${s.fldName}</option>`;
        targetStoreSelect.innerHTML += `<option value="${s.fldID}">${s.fldName}</option>`;
      });

      if (stores.length > 1) targetStoreSelect.selectedIndex = 1;
    } catch(e) {
      sourceStoreSelect.innerHTML = `<option value="1">المستودع العام1</option><option value="2">مستودع المعلا</option>`;
      targetStoreSelect.innerHTML = `<option value="2">مستودع المعلا</option><option value="1">المستودع العام1</option>`;
    }
  }
  // Fetch next transfer number
  fetchNextTransferNumber(tabId);
}

