// 2. Send Unbalanced Entries WhatsApp PDF
window.sendUnbalancedEntriesWhatsApp = async function(tabId) {
  const data = (state.lastUnbalancedResult && state.lastUnbalancedResult[tabId]) ? state.lastUnbalancedResult[tabId] : [];
  if (!data || data.length === 0) {
    showToast("لا توجد قيود غير متزنة لإرسالها.", "warning");
    return;
  }

  const phoneInput = prompt("أدخل رقم الواتساب لإرسال كشف القيود غير المتزنة كـ PDF (مثل 967777777777):", "");
  if (phoneInput === null) return;

  const cleanPhone = phoneInput.replace(/[^0-9]/g, '');
  if (!cleanPhone || cleanPhone.length < 8) {
    showToast("رقم الواتساب غير صالح.", "error");
    return;
  }

  showToast("جاري إعداد تقرير القيود غير المتزنة وإرساله بالواتساب...", "info");

  try {
    const res = await fetch('/api/trial-balance/unbalanced/send-whatsapp-pdf', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-user-id': state.currentUser ? state.currentUser.id : '1' },
      body: JSON.stringify({ phone: cleanPhone })
    });
    const result = await res.json();
    if (!result.success) throw new Error(result.error || result.message);
    showToast("تم إرسال كشف القيود غير المتزنة بالواتساب بنجاح!", "success");
  } catch (err) {
    console.error("WhatsApp Unbalanced error:", err);
    showToast(`فشل إرسال التقرير: ${err.message}`, "error");
  }
};

