// 6. POS Category Filter & Refresh
window.filterPosCategory = function(tabId, categoryName, btnEl) {
  const btns = document.querySelectorAll(`#posCategoryBtns-${tabId} .pos-cat-btn`);
  btns.forEach(b => {
    b.classList.remove('btn-primary');
    b.classList.add('btn-secondary');
  });
  if (btnEl) {
    btnEl.classList.remove('btn-secondary');
    btnEl.classList.add('btn-primary');
  }

  const container = document.querySelector(`#pane-${tabId} .products-grid-container`) || document.querySelector(`#pane-${tabId}`);
  if (!container) return;

  const cards = container.querySelectorAll('[onclick*="addPosItem"]');
  cards.forEach(card => {
    if (categoryName === 'الكل') {
      card.style.display = 'block';
    } else {
      const text = card.textContent.toLowerCase();
      const catLower = categoryName.toLowerCase().replace('ملابس', '').replace('أحذية', '').trim();
      if (text.includes(catLower) || categoryName.includes('ملابس') && (text.includes('تيشيرت') || text.includes('قميص') || text.includes('فستان')) ||
          categoryName.includes('أحذية') && text.includes('حذاء') ||
          categoryName.includes('سوائل') && (text.includes('ماء') || text.includes('عصير') || text.includes('مشروب')) ||
          categoryName.includes('عطور') && (text.includes('عطر') || text.includes('ساعة'))) {
        card.style.display = 'block';
      } else {
        card.style.display = 'none';
      }
    }
  });
  showToast(`تمت التصفية حسب: ${categoryName}`, "info");
};

window.refreshPosItems = function(tabId) {
  showToast("تم تحديث قائمة أصناف نقاط البيع بنجاح.", "success");
};

